-- GENERATED by tools/gamekit/bundle_reader.py from apps/rss/src/ and tools/gamekit/ai.lua, aiui.lua
-- -- edit those files, not this one.

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['ai'] = function()
-- Asking an AI about the article on screen, shared by RSS and Hacker News (their bundle.py puts
-- it in as require('ai')): the services and the three kinds of interface they speak (Claude, any
-- OpenAI-compatible server, Gemini), the request each one takes and the answer each one gives,
-- and the logic of the Settings → AI page. Nothing here draws or touches the network: the app
-- sends what A.request builds and shows what A.value gives.
--
-- The settings live in the app's cfg: aion (boolean), aiprov, aiurl, aikey, aimodel, ailang,
-- aiextra (strings).
--
-- A conversation is a list of { role = 'user' | 'assistant', text = ... }. The article goes into
-- the system prompt, so every follow-up question still sees it.

local A = {}

-- The services offered in Settings → AI, in the list's order: each speaks one of the three kinds
-- of interface (claude, openai, gemini), with its own address and a model to start with (the
-- Model setting replaces it). Ollama and Other have no address of their own: it is asked when
-- they are chosen, and a key is optional there (local servers need none).
A.PROVIDERS = {
  { id = 'claude', label = 'Claude (Anthropic)', name = 'Claude', kind = 'claude', url = 'https://api.anthropic.com/v1', model = 'claude-opus-5-5' },
  { id = 'openai', label = 'OpenAI', name = 'OpenAI', kind = 'openai', url = 'https://api.openai.com/v1', model = 'gpt-5-mini' },
  { id = 'gemini', label = 'Gemini (Google)', name = 'Gemini', kind = 'gemini', url = 'https://generativelanguage.googleapis.com/v1beta', model = 'gemini-2.5-flash' },
  { id = 'openrouter', label = 'OpenRouter', name = 'OpenRouter', kind = 'openai', url = 'https://openrouter.ai/api/v1', model = 'openrouter/auto' },
  { id = 'groq', label = 'Groq', name = 'Groq', kind = 'openai', url = 'https://api.groq.com/openai/v1', model = 'llama-3.3-70b-versatile' },
  { id = 'mistral', label = 'Mistral', name = 'Mistral', kind = 'openai', url = 'https://api.mistral.ai/v1', model = 'mistral-small-latest' },
  { id = 'deepseek', label = 'DeepSeek', name = 'DeepSeek', kind = 'openai', url = 'https://api.deepseek.com/v1', model = 'deepseek-flash' },
  { id = 'ollama', label = 'Ollama (on your network)', name = 'Ollama', kind = 'openai', url = '', model = 'llama3.2', keyless = true,
    hint = 'http://192.168.1.' },
  { id = 'other', label = 'Other (OpenAI-compatible)', name = 'AI', short = 'Other', kind = 'openai', url = '', model = '', keyless = true,
    hint = 'https://' },
}
A.PROV = {}
for _, p in ipairs(A.PROVIDERS) do A.PROV[p.id] = p end

-- the ready questions: the button's name and what is asked
A.PRESETS = {
  { 'Summarize', 'Summarize this article in a few short paragraphs.' },
  { 'Key points', 'List the key points of this article.' },
  { 'Explain simply', 'Explain this article simply, for someone new to the subject.' },
  { 'Background', 'What background or context helps to understand this article?' },
  { 'What is missing?', 'What might this article leave out, and which of its claims are weak or one-sided?' },
}

-- more ready questions when a discussion goes along (Hacker News comments)
A.DISCUSSION = {
  { 'The discussion', 'Summarize the discussion in the comments: the main points of view and the most useful answers.' },
  { 'Disagreements', 'Where do the commenters disagree, and what are the strongest arguments on each side?' },
}

local ARTICLE_MAX = 24000      -- bytes of article text sent along
local BODY_MAX = 60000         -- the reader sends at most 65536 bytes
local COMMENTS_ROOM = 52000    -- article text and comments together, at most

-- s cut to at most n bytes, on a whole UTF-8 character
local function cut(s, n)
  if #s <= n then return s end
  local i = n
  while i > 0 and s:byte(i + 1) and s:byte(i + 1) >= 0x80 and s:byte(i + 1) < 0xC0 do i = i - 1 end
  return s:sub(1, i)
end
A.cut = cut

function A.prov(cfg) return A.PROV[cfg.aiprov] or A.PROV.claude end
function A.kind(cfg) return A.prov(cfg).kind end
function A.url(cfg) return ((cfg.aiurl ~= '' and cfg.aiurl or A.prov(cfg).url):gsub('/+$', '')) end
function A.model(cfg) return cfg.aimodel ~= '' and cfg.aimodel or A.prov(cfg).model end

-- switched on and able to ask: an address, and a key where the service needs one
function A.ready(cfg)
  if not cfg.aion or A.url(cfg) == '' then return false end
  return cfg.aikey ~= '' or A.prov(cfg).keyless == true
end

-- Extra parameters (Settings → AI): a JSON object merged into every request body, nested objects
-- into nested objects; null removes a field (e.g. {"fallbacks":null}). Returns the table, or nil
-- and why. decode is ctx.json's decode.
function A.extra(s, decode)
  if not s or not s:match('%S') then return nil end
  local ok, t = pcall(decode, s)
  if not ok or type(t) ~= 'table' then return nil, 'Extra parameters: not valid JSON' end
  if t[1] ~= nil then return nil, 'Extra parameters: a JSON object {...} is needed' end
  return t
end

local function merge(dst, src, null)
  for k, v in pairs(src) do
    if null ~= nil and v == null then dst[k] = nil
    elseif type(v) == 'table' and type(dst[k]) == 'table' and v[1] == nil then merge(dst[k], v, null)
    else dst[k] = v end
  end
end

-- the system prompt: how to answer on this screen, then the article
-- art: { title, feed, date, url, text, comments, what }. text is the article (may be empty: then
-- only its link is given); comments a discussion already written out as text (Hacker News);
-- what names the thing read ('an article' by default).
function A.system(cfg, art)
  local text = (art.text or ''):gsub('%[%[img:%d+%]%]', ''):gsub('\n\n\n+', '\n\n')
  local short = #text > ARTICLE_MAX
  text = cut(text, ARTICLE_MAX)
  local lines = {
    'You help someone who is reading ' .. (art.what or 'an article') .. ' on a small black-and-white e-reader.',
    'Reply in plain text: short paragraphs, "- " for list items, no tables, no code blocks, no links to follow.',
    'Be concise unless asked for more. If the text below seems to be only a summary, say so when it matters.',
  }
  if (cfg.ailang or '') ~= '' then lines[#lines + 1] = 'Answer in ' .. cfg.ailang .. '.' end
  lines[#lines + 1] = ''
  lines[#lines + 1] = 'Title: ' .. (art.title or '')
  if (art.feed or '') ~= '' then lines[#lines + 1] = 'Source: ' .. art.feed end
  if (art.date or '') ~= '' then lines[#lines + 1] = 'Date: ' .. art.date end
  if (art.url or '') ~= '' then lines[#lines + 1] = 'Link: ' .. art.url end
  lines[#lines + 1] = ''
  if text:match('%S') then
    lines[#lines + 1] = text .. (short and '\n\n[The article goes on; only its beginning is given here.]' or '')
  elseif (art.url or '') ~= '' then
    lines[#lines + 1] = '[Only the link of the article is given here, not its text: say so when it matters.]'
  end
  if art.comments and art.comments:match('%S') then
    local room = math.max(8000, COMMENTS_ROOM - #text)
    local c = art.comments
    if #c > room then c = cut(c, room) .. '\n[More comments follow; they are left out here.]' end
    lines[#lines + 1] = ''
    lines[#lines + 1] = 'The discussion (each comment as "author: text"; a reply is indented under the comment it answers):'
    lines[#lines + 1] = c
  end
  return table.concat(lines, '\n')
end

-- Claude's newest models take a few extras: low effort (quick answers) on the 5 family, and the
-- server-side fallback to another model where a model declines
local function claude_extras(model, body, headers)
  if model:match('^claude%-%a+%-5') then body.output_config = { effort = 'low' } end
  if model == 'claude-opus-5-5' or model == 'claude-opus-5' or model == 'claude-fable-5-1' or model == 'claude-sonnet-5-5' then
    body.fallbacks = 'default'
    headers['anthropic-beta'] = 'server-side-fallback-2026-07-01'
  end
end

local function body_for(kind, model, sys, msgs)
  if kind == 'claude' then
    local m = {}
    for _, x in ipairs(msgs) do m[#m + 1] = { role = x.role, content = x.text } end
    return { model = model, max_tokens = 4096, system = sys, messages = m }
  elseif kind == 'gemini' then
    local c = {}
    for _, x in ipairs(msgs) do c[#c + 1] = { role = x.role == 'assistant' and 'model' or 'user', parts = { { text = x.text } } } end
    return { systemInstruction = { parts = { { text = sys } } }, contents = c }
  end
  local m = { { role = 'system', content = sys } }
  for _, x in ipairs(msgs) do m[#m + 1] = { role = x.role, content = x.text } end
  return { model = model, messages = m }
end

local function message_of(d)
  if type(d) ~= 'table' then return nil end
  local e = d.error
  if type(e) == 'table' and e.message then return tostring(e.message) end
  if type(e) == 'string' then return e end
  return nil
end

-- Web search: a switch at the top of the ready questions (Web search: on / off), for every
-- question asked while it is on, the ready ones too; off again for each new article. Where the service
-- has it: Claude, Gemini and OpenRouter as a tool the model calls itself, OpenAI through its
-- Responses API, DeepSeek as a separate search the app makes first (A.search_request); the
-- others (Groq, Mistral, Ollama, Other) do not offer it here.
A.WEB = { claude = 'tool', gemini = 'tool', openrouter = 'tool', openai = 'responses', deepseek = 'search' }
function A.web_ok(cfg) return A.WEB[A.prov(cfg).id] ~= nil end
function A.web_first(cfg) return A.WEB[A.prov(cfg).id] == 'search' end

-- What DeepSeek's search looks for is written by the model first: a short query from the whole
-- article, the conversation and the question (a ready question such as "What background ...?"
-- says nothing of the article by itself). The request is the answer's own (the same system text
-- with the article, the same conversation) with an instruction after the question, so the answer
-- that follows starts the same way and DeepSeek serves that part from its cache. When it fails,
-- the article's title and the question are searched.
local QUERY_ASK = '[Before answering: reply only with one web search query (at most 12 words and under 100 characters) that finds what is'
  .. ' needed to answer this, using the article and the conversation above. No quotes, no explanation.]'
function A.query_request(cfg, art, msgs, J)
  local list = {}
  for i, m in ipairs(msgs) do list[i] = m end
  local last = list[#list]
  if not last or last.role ~= 'user' then return nil, 'no question' end
  list[#list] = { role = 'user', text = last.text .. '\n\n' .. QUERY_ASK }
  return A.request(cfg, art, list, { encode = J.encode, extra = J.extra, null = J.null, max_tokens = 60 })
end
-- the query from that answer, or the title and the question when there is none
function A.query_text(cfg, resp, decode, art, question)
  local text = resp and A.answer(cfg, resp, decode)
  local q = text and text:match('[^\n]*%S[^\n]*')
  if q then q = q:gsub('[%*`]', ''):gsub('^%s*[#>%-]*%s*', ''):gsub('^["\']+', ''):gsub('["\']+%s*$', ''):gsub('%s+$', '') end
  if not q or q == '' or #q > 200 then q = ((art.title or '') .. ' ' .. question):gsub('^%s+', '') end
  return A.short_query(q)
end

-- DeepSeek's search takes a query (and ori_question) of 1 to 128 Unicode characters: longer ones
-- are cut after a whole word
A.QUERY_MAX = 128
function A.short_query(q)
  q = tostring(q or ''):gsub('%s+', ' '):gsub('^ ', ''):gsub(' $', '')
  local n = utf8.len(q)
  if not n then q = cut(q, A.QUERY_MAX); n = utf8.len(q) or #q end   -- not valid UTF-8: bytes
  if n <= A.QUERY_MAX then return q end
  local c = q:sub(1, (utf8.offset(q, A.QUERY_MAX + 1) or #q + 1) - 1)
  if q:sub(#c + 1, #c + 1) == ' ' then return c end              -- the cut fell between words
  return c:match('^(.*%S)%s+%S*$') or c
end

-- DeepSeek's search (POST /v1/tools/search, the same key): the request for a query, with the
-- question it serves (ori_question, which DeepSeek uses to rank the results)
function A.search_request(cfg, query, encode, question)
  local q = A.short_query(query)
  if q == '' then q = 'news' end
  local oq = question and A.short_query(question) or ''
  local body = encode(oq ~= '' and { query = q, ori_question = oq, count = 5 } or { query = q, count = 5 })
  if type(body) ~= 'string' then return nil, 'could not encode the search' end
  return { url = A.url(cfg) .. '/tools/search', method = 'POST', body = body,
           headers = { ['content-type'] = 'application/json', ['Authorization'] = 'Bearer ' .. (cfg.aikey or '') } }
end

-- its results as text to go with the question (at most about 6 KB), or nil and why
function A.search_text(resp, decode)
  if type(resp) ~= 'table' or type(resp.body) ~= 'string' then return nil, 'the search gave no answer' end
  local st = tonumber(resp.status)
  local ok, d = pcall(decode, resp.body)
  if st and st >= 400 then local m = ok and message_of(d); return nil, 'search: HTTP ' .. st .. (m and (': ' .. m) or '') end
  if not ok or type(d) ~= 'table' or type(d.results) ~= 'table' or #d.results == 0 then return nil, 'the search found nothing' end
  local out = { 'Web search results (use them when they help, and name the source):' }
  for k, r in ipairs(d.results) do
    if type(r) == 'table' then
      local head = k .. '. ' .. tostring(r.title or '') .. ' (' .. tostring(r.url or '') .. (r.date and r.date ~= '' and (', ' .. tostring(r.date)) or '') .. ')'
      out[#out + 1] = head .. '\n' .. cut(tostring(r.summary or r.snippet or ''), 1100)
    end
  end
  return cut(table.concat(out, '\n\n'), 6000)
end

-- the request for the conversation so far: opts for ctx.net:request, or nil and why.
-- J: { encode = ctx.json's encode, extra = A.extra's table or nil, null = ctx.json.null,
-- web = true for a web search where the service runs it itself }. A conversation too long for
-- one request loses its oldest exchanges (the first question stays); the article is shortened last.
function A.request(cfg, art, msgs, J)
  local kind, model, base = A.kind(cfg), A.model(cfg), A.url(cfg)
  local key = cfg.aikey or ''
  local headers = { ['content-type'] = 'application/json' }
  local url
  if kind == 'claude' then
    url = base .. '/messages'
    headers['x-api-key'] = key
    headers['anthropic-version'] = '2023-06-01'
  elseif kind == 'gemini' then
    url = base .. '/models/' .. model .. ':generateContent'
    headers['x-goog-api-key'] = key
  else
    url = base .. '/chat/completions'
    if key ~= '' then headers['Authorization'] = 'Bearer ' .. key end
  end
  local web = J.web and A.WEB[A.prov(cfg).id] or nil
  if web == 'responses' then url = base .. '/responses' end
  local sys = A.system(cfg, art)
  local list = {}
  for i, x in ipairs(msgs) do list[i] = x end
  for _ = 1, 40 do
    local body = body_for(kind, model, sys, list)
    if kind == 'claude' then claude_extras(model, body, headers) end
    if J.max_tokens and kind == 'openai' then body.max_tokens = J.max_tokens end   -- a short answer (the search query)
    if web == 'responses' then                       -- OpenAI: the Responses API with its web_search tool
      local input = {}
      for _, x in ipairs(list) do input[#input + 1] = { role = x.role, content = x.text } end
      body = { model = model, instructions = sys, input = input, tools = { { type = 'web_search' } } }
    elseif web == 'tool' and kind == 'claude' then   -- the basic web search: quick enough for the reader's 60 s
      body.tools = { { type = 'web_search_20250305', name = 'web_search', max_uses = 2 } }
    elseif web == 'tool' and kind == 'openai' then   -- OpenRouter's server tool
      body.tools = { { type = 'openrouter:web_search', parameters = { max_results = 5 } } }
    end
    if type(J.extra) == 'table' then merge(body, J.extra, J.null) end
    local s = J.encode(body)
    if type(s) ~= 'string' then return nil, 'could not encode the question' end
    -- Gemini's tool is an empty object, which ctx.json writes only as [] (an empty table)
    if web == 'tool' and kind == 'gemini' then s = s:sub(1, -2) .. ',"tools":[{"google_search":{}}]}' end
    if #s <= BODY_MAX then return { url = url, method = 'POST', headers = headers, body = s } end
    if #list > 3 then
      table.remove(list, 2); table.remove(list, 2)          -- the oldest answer and question after the first
    else
      sys = cut(sys, math.max(2000, #sys - (#s - BODY_MAX) - 500))
    end
  end
  return nil, 'the question is too long'
end

-- the answer's text from the reply (resp from ctx.net:request, decode = ctx.json's decode), or nil
-- and a short reason
function A.answer(cfg, resp, decode)
  if type(resp) ~= 'table' then return nil, 'no answer' end
  local st, body = tonumber(resp.status), resp.body
  if type(body) ~= 'string' or body == '' then
    return nil, (resp.err and tostring(resp.err)) or (st and ('HTTP ' .. st)) or 'no answer'
  end
  local ok, d = pcall(decode, body)
  if not ok or type(d) ~= 'table' then return nil, (st and st >= 400 and ('HTTP ' .. st .. ' ') or 'not JSON: ') .. body:sub(1, 60) end
  if st and st >= 400 then
    local m = message_of(d)
    if st == 401 or st == 403 then m = 'the key was not accepted' .. (m and (': ' .. m) or '') end
    return nil, 'HTTP ' .. st .. (m and (': ' .. m) or '')
  end
  local kind, parts = A.kind(cfg), {}
  if kind == 'claude' then
    if d.stop_reason == 'refusal' then return nil, 'the model declined to answer' end
    for _, b in ipairs(type(d.content) == 'table' and d.content or {}) do
      if type(b) == 'table' and b.type == 'text' and type(b.text) == 'string' then parts[#parts + 1] = b.text end
    end
    if d.stop_reason == 'max_tokens' then parts[#parts + 1] = ' …' end
    if #parts == 0 and d.stop_reason == 'pause_turn' then return nil, 'the search took too long: ask again' end
  elseif kind == 'gemini' then
    local c = type(d.candidates) == 'table' and d.candidates[1]
    local content = type(c) == 'table' and c.content
    for _, p in ipairs(type(content) == 'table' and type(content.parts) == 'table' and content.parts or {}) do
      if type(p) == 'table' and type(p.text) == 'string' and not p.thought then parts[#parts + 1] = p.text end
    end
    if #parts == 0 and type(d.promptFeedback) == 'table' and d.promptFeedback.blockReason then
      return nil, 'blocked: ' .. tostring(d.promptFeedback.blockReason)
    end
  elseif type(d.output) == 'table' then             -- OpenAI's Responses API (web search)
    for _, item in ipairs(d.output) do
      if type(item) == 'table' and item.type == 'message' and type(item.content) == 'table' then
        for _, c in ipairs(item.content) do
          if type(c) == 'table' and c.type == 'output_text' and type(c.text) == 'string' then parts[#parts + 1] = c.text end
        end
      end
    end
    if d.status == 'incomplete' then parts[#parts + 1] = ' …' end
  else
    local c = type(d.choices) == 'table' and d.choices[1]
    local m = type(c) == 'table' and c.message
    if type(m) == 'table' and type(m.content) == 'string' then parts[1] = m.content end
  end
  local text = table.concat(parts):gsub('^%s+', ''):gsub('%s+$', '')
  if text == '' then return nil, message_of(d) or 'an empty answer' end
  return text
end

-- Markdown as this screen shows it: headings as "# ", list items as "• ", no bold or code marks.
-- Single line breaks stay (each line is laid out on its own), blank lines part paragraphs.
function A.plain(s)
  local out = {}
  for line in (s:gsub('\r', '') .. '\n'):gmatch('([^\n]*)\n') do
    local t = line:gsub('^%s+', '')
    local head = t:match('^#+%s+(.*)$')
    if head then t = '# ' .. head
    elseif t:match('^[%-%*%+]%s+') then t = '• ' .. t:gsub('^[%-%*%+]%s+', '')
    elseif t:match('^```') or t:match('^%-%-%-+$') or t:match('^%*%*%*+$') then t = '' end
    t = t:gsub('%*%*(.-)%*%*', '%1'):gsub('__(.-)__', '%1'):gsub('`', '')
    out[#out + 1] = t
  end
  return (table.concat(out, '\n'):gsub('\n\n\n+', '\n\n'))
end

-- ai.txt in the app's folder: service= (or kind=), url=, key=, model=, lang=, extra= (and on=0 to
-- keep it off); returns the settings it holds (keys as in cfg) or nil
function A.read_file(s)
  if type(s) ~= 'string' then return nil end
  local map = { kind = 'aiprov', service = 'aiprov', provider = 'aiprov', url = 'aiurl', address = 'aiurl', key = 'aikey',
                model = 'aimodel', lang = 'ailang', extra = 'aiextra', on = 'aion' }
  local out, n = {}, 0
  for line in (s:gsub('\r', '') .. '\n'):gmatch('([^\n]*)\n') do
    local k, v = line:match('^%s*(%a+)%s*=%s*(.-)%s*$')
    k = k and map[k:lower()]
    if k then out[k] = v; n = n + 1 end
  end
  if n == 0 then return nil end
  if out.aiprov then
    local k = out.aiprov:lower()
    if not A.PROV[k] then
      local found = (k:find('compat') or k:find('other')) and 'other' or k:find('anthropic') and 'claude' or k:find('google') and 'gemini' or nil
      if not found then for _, p in ipairs(A.PROVIDERS) do if k:find(p.id, 1, true) then found = p.id; break end end end
      k = found or 'other'
    end
    out.aiprov = k
  elseif out.aiurl then
    out.aiprov = 'other'
  end
  if out.aion then out.aion = not (out.aion == '0' or out.aion:lower() == 'off')
  else out.aion = true end
  return out
end

------------------------------------------------------------------ the Settings → AI page

A.SET = { { 'aion', 'AI' }, { 'aiprov', 'Service' }, { 'aiurl', 'Address' }, { 'aikey', 'Key' },
          { 'aimodel', 'Model' }, { 'ailang', 'Answer in' }, { 'aiextra', 'Extra parameters (JSON)' },
          { 'aibtn', 'My buttons' }, { 'aitest', 'Connection' } }
A.HALF = { aion = true, aiprov = true, aimodel = true, ailang = true, aibtn = true, aitest = true }   -- half a row in portrait
A.DEFAULTS = { aion = false, aiprov = 'claude', aiurl = '', aikey = '', aimodel = '', ailang = '', aiextra = '' }
-- aion comes from config.txt as '1' / '0'
function A.normalize(cfg) cfg.aion = cfg.aion == true or cfg.aion == '1' end

-- anything of it set (the app saves its AI lines only then)
function A.used(cfg)
  for k, v in pairs(A.DEFAULTS) do if cfg[k] ~= v then return true end end
  return false
end

-- the AI lines of the app's config.txt ("\naion=1\naiprov=..."), or '' while nothing is set
function A.cfg_lines(cfg)
  if not A.used(cfg) then return '' end
  return '\naion=' .. (cfg.aion and '1' or '0') .. '\naiprov=' .. cfg.aiprov .. '\naiurl=' .. cfg.aiurl .. '\naikey=' .. cfg.aikey
    .. '\naimodel=' .. cfg.aimodel .. '\nailang=' .. cfg.ailang .. '\naiextra=' .. cfg.aiextra
end

-- a field's value as the page shows it (the key only as its ends)
function A.value(cfg, k)
  local P = A.prov(cfg)
  if k == 'aion' then return cfg.aion and 'on' or 'off' end
  if k == 'aiprov' then return P.short or P.name end
  if k == 'aiurl' then return cfg.aiurl ~= '' and cfg.aiurl or (P.url ~= '' and (P.url:gsub('^https://', '') .. '  (default)') or '(needed)') end
  if k == 'aikey' then
    local key = cfg.aikey
    if key == '' then return P.keyless and '(none needed)' or '(empty)' end
    return (#key > 12 and (key:sub(1, 6) .. '…' .. key:sub(-4)) or '****') .. '  (' .. #key .. ' characters)'
  end
  if k == 'aimodel' then return cfg.aimodel ~= '' and cfg.aimodel or (P.model ~= '' and P.model or '(server default)') end
  if k == 'aiextra' then return cfg.aiextra ~= '' and cfg.aiextra or '(none)' end
  if k == 'ailang' then return cfg.ailang ~= '' and cfg.ailang or '(as asked)' end
  if k == 'aibtn' then return #A.buttons() .. ' of ' .. A.BUTTONS_MAX end
  return 'Tap to test'
end

-- Your own ready questions: ai_buttons.txt in the app's folder, one "Label | question" a line (a
-- line without "|" is its own label, cut short); lines starting with # are left out. Edited on the
-- reader (Settings → AI → My buttons) or over USB. At most BUTTONS_MAX.
A.BUTTONS_FILE, A.BUTTONS_MAX = 'ai_buttons.txt', 6
function A.parse_button(line)
  line = tostring(line or ''):gsub('\r', ''):gsub('^%s+', ''):gsub('%s+$', '')
  if line == '' or line:sub(1, 1) == '#' then return nil end
  local label, q = line:match('^(.-)%s*|%s*(.+)$')
  if not label or label == '' then
    q = q or line
    label = q:gsub('%s*|%s*', ' ')
    if #label > 22 then label = cut(label, 21) .. '…' end
  end
  return { label = label, q = q }
end
function A.parse_buttons(s)
  local out = {}
  for line in (tostring(s or '') .. '\n'):gmatch('([^\n]*)\n') do
    local b = A.parse_button(line)
    if b and #out < A.BUTTONS_MAX then out[#out + 1] = b end
  end
  return out
end
local buttons_cache = nil
-- the buttons, read from the card when asked to (reload) or the first time
function A.buttons(reload)
  if reload or not buttons_cache then
    local ok, s = pcall(function()
      if not (ctx.files and ctx.files:exists(A.BUTTONS_FILE)) then return '' end
      return ctx.files:read(A.BUTTONS_FILE, 0, 8192)
    end)
    buttons_cache = A.parse_buttons(ok and s or '')
  end
  return buttons_cache
end
-- the buttons written back (after an edit on the reader)
function A.save_buttons(list)
  local t = { '# Your own AI buttons: one "Label | question" a line, at most ' .. A.BUTTONS_MAX .. '.' }
  for _, b in ipairs(list) do t[#t + 1] = b.label .. ' | ' .. b.q end
  buttons_cache = list
  return pcall(function() return ctx.files:write(A.BUTTONS_FILE, table.concat(t, '\n') .. '\n') end)
end

-- the keyboard for a text field: its title and starting text
function A.field(cfg, k)
  local P = A.prov(cfg)
  local titles = { aiurl = P.url ~= '' and ('Address (empty: ' .. P.url .. ')') or 'Address, e.g. http://192.168.1.5:11434/v1',
                   aikey = 'API key', aimodel = P.model ~= '' and ('Model (empty: ' .. P.model .. ')') or 'Model',
                   ailang = 'Answer in (e.g. Turkish; empty: as asked)',
                   aiextra = 'Extra parameters (JSON), e.g. {"max_tokens":800}' }
  local start = cfg[k] or ''
  if k == 'aiurl' and start == '' and P.hint then start = P.hint end
  return titles[k] or k, start
end

-- what was typed into field k: kept in cfg, or nil and why not (the caller saves)
function A.store(cfg, k, v, decode)
  v = v:gsub('^%s+', ''):gsub('%s+$', '')
  if k == 'aiurl' and v == A.prov(cfg).hint then v = '' end
  if k == 'aiextra' then
    local _, err = A.extra(v, decode)
    if err then return nil, err .. ' (not saved)' end
  end
  cfg[k] = v
  return true
end

-- AI on / off; on without what it needs says what is missing
function A.toggle(cfg)
  cfg.aion = not cfg.aion
  if cfg.aion and not A.ready(cfg) then return A.url(cfg) == '' and 'now set the address' or 'now add the key' end
  return nil
end

-- a service from the list: its own address and model, and no Extra parameters (they differ from
-- service to service); true when its address must be typed now (Ollama, Other)
function A.choose(cfg, id)
  local P = A.PROV[id]
  if not P then return false end
  if cfg.aiprov ~= id then cfg.aiprov, cfg.aiurl, cfg.aimodel, cfg.aiextra = id, '', '', '' end
  return P.url == '' and cfg.aiurl == ''
end

-- ai.txt's text taken into cfg; true when it held settings (the caller saves and deletes the file)
function A.take(cfg, s)
  local got = A.read_file(s)
  if not got then return false end
  for k, v in pairs(got) do cfg[k] = v end
  return true
end

-- the conversation's buttons: More leads to the ready questions, your own question and the web
-- search switch
function A.chat_bar(cfg) return { 'Back', 'Prev', 'Next', 'More' } end

-- the connection test: a one-word question
A.TEST_ART = { title = 'Test', text = 'This is a connection test.' }
A.TEST_MSGS = { { role = 'user', text = 'Reply with the single word OK.' } }

-- the ready questions' rows { label, 'web' } | { label, 'ask', question } | { label, 'own' } |
-- { label, 'new' }: the web search switch where the service has a web search, the presets (and
-- more for a discussion), your own buttons, Translate when an answer language is set, your own
-- question, and Start over once there is a conversation
-- (no_article: only the discussion is sent, so the article's questions are left out; web: the
-- web search switch's state, shown first where the service has a web search)
function A.items(cfg, has_chat, more, no_article, web)
  local t = {}
  if A.web_ok(cfg) then t[#t + 1] = { 'Web search: ' .. (web and 'on' or 'off'), 'web' } end
  if not no_article then for _, p in ipairs(A.PRESETS) do t[#t + 1] = { p[1], 'ask', p[2] } end end
  for _, p in ipairs(more or {}) do t[#t + 1] = { p[1], 'ask', p[2] } end
  for _, b in ipairs(A.buttons()) do t[#t + 1] = { b.label, 'ask', b.q } end
  if cfg.ailang ~= '' and not no_article then t[#t + 1] = { 'Translate', 'ask', 'Translate this article into ' .. cfg.ailang .. '.' } end
  t[#t + 1] = { 'Your question', 'own' }
  if has_chat then t[#t + 1] = { 'Start over', 'new' } end
  return t
end

return A
end

__mods['aiui'] = function()
-- The optional AI questions' screens for the reading apps built like RSS (RSS, Instapaper,
-- Readwise, wallabag): Settings → AI (aiset), the Service list (aiprov), your own buttons
-- (aibtns), the ready questions (aimenu) and the conversation (chat). ai.lua does the requests and answers; this does the
-- screens, drawn with the app's own helpers, which the app hands over in E:
--
--   cfg, save(), note(s), refresh(), submit(opts, label, timeout_ms, fn(resp, err)), keep_wifi(),
--   wrap(out, text, font_name, width, indent) (the app's wrap_para), style() ({ head, body, meta }),
--   bar(gg, labels), bar_hit(x, n), cell(i, y0, row_h, h), fit(s, font, w), short(s, n),
--   draw_status(gg), busy(), status() (the status line's text), dims() (W, H, TOP),
--   get_screen(), set_screen(s), article() ({ id, title, feed, date, url, text } of the article
--   open, or nil while it loads), folder (e.g. 'AppFiles/rss'), what (e.g. 'an article').
--
-- The app's article bar shows an AI button only when M.on(); Settings shows an AI cell
-- (M.value(), M.open_settings()). Its draw / tap / Back / paging pass to M while M.handles(screen).
-- Off (or not set up), nothing of it shows anywhere.

local A = require('ai')
local U = {}

function U.new(E)
  local M = {}
  local cfg = E.cfg
  local chat = { id = nil, msgs = {}, lines = {}, starts = { 1 }, page = 1, pages = 1, waiting = false }
  local SCREENS = { chat = true, aimenu = true, aiset = true, aiprov = true, aibtns = true }
  local web = false                                -- the web search switch: off for each new article
  local function dec(s) return ctx.json:decode(s) end
  local function enc(v) return ctx.json:encode(v) end
  local function F() return ctx.fonts end
  local function J()
    local extra, err = A.extra(cfg.aiextra, dec)
    if err then return nil, err end
    return { encode = enc, extra = extra, null = ctx.json.null }
  end

  function M.on() return A.ready(cfg) end
  function M.handles(s) return SCREENS[s] == true end
  function M.chat() return chat end

  -- an answer's text: headings, list items and paragraphs as in an article
  local function text_lines(out, text, S, W)
    for raw in (text .. '\n\n'):gmatch('(.-)\n\n') do
      local para = raw:gsub('^\n+', ''):gsub('\n+$', '')
      if para ~= '' then
        for line in (para .. '\n'):gmatch('([^\n]*)\n') do
          if line:sub(1, 2) == '# ' then E.wrap(out, line:sub(3), S.head, W - 24, 0)
          elseif line:sub(1, 4) == '• ' then E.wrap(out, line, S.body, W - 40, 16)
          elseif line ~= '' then E.wrap(out, line, S.body, W - 24, 0) end
        end
        out[#out + 1] = { s = '', f = 'small', h = 10, x = 0 }
      end
    end
  end

  -- to_last: show the page where the last message starts (a new question or answer)
  function M.layout(to_last)
    local W, H, TOP = E.dims()
    if E.reset then E.reset() end                    -- the app's measure cache
    local S, out, last_at = E.style(), {}, 1
    for _, m in ipairs(chat.msgs) do
      if m.role == 'user' then
        last_at = #out + 1                         -- a new answer opens at its question
        E.wrap(out, '» ' .. (m.label or m.text), S.meta, W - 48, 24)
        out[#out + 1] = { s = '', f = 'small', h = 12, x = 0 }
      else
        text_lines(out, A.plain(m.text), S, W)
        out[#out + 1] = { s = '', f = 'small', h = 6, x = 0, rule = true }
        out[#out + 1] = { s = '', f = 'small', h = 10, x = 0 }
      end
    end
    if chat.waiting then E.wrap(out, type(chat.waiting) == 'string' and chat.waiting or ('Asking ' .. A.prov(cfg).name .. '…'), 'small', W - 24, 0) end
    chat.lines, chat.starts = out, { 1 }
    local avail, used = H - TOP - 40, 0
    for i, ln in ipairs(out) do
      if used + ln.h > avail and used > 0 then chat.starts[#chat.starts + 1] = i; used = 0 end
      used = used + ln.h
    end
    -- a last page holding only an answer's closing rule and gaps is dropped (it showed empty)
    while #chat.starts > 1 do
      local blank = true
      for i = chat.starts[#chat.starts], #out do if out[i].s ~= '' then blank = false; break end end
      if not blank then break end
      for i = #out, chat.starts[#chat.starts], -1 do out[i] = nil end   -- its lines go too
      chat.starts[#chat.starts] = nil
    end
    chat.pages = #chat.starts
    if to_last then
      chat.page = 1
      for p, first in ipairs(chat.starts) do if first <= last_at then chat.page = p end end
    end
    chat.page = math.max(1, math.min(chat.page, chat.pages))
  end
  -- the screen turned: the conversation laid out again
  function M.relayout() if #chat.lines > 0 then M.layout(false) end end

  -- the AI button: the ready questions, or the conversation once there is one
  function M.open()
    local a = E.article()
    if not a then E.note('wait for the article'); return end
    if chat.id ~= a.id then chat = { id = a.id, msgs = {}, lines = {}, starts = { 1 }, page = 1, pages = 1, waiting = false }; web = false end
    A.buttons(true)                                  -- ai_buttons.txt may have changed over USB
    if #chat.msgs > 0 then M.layout(false); E.set_screen('chat') else E.set_screen('aimenu') end
  end

  -- a question: a ready one (label), or your own; with a web search while the switch is on, where
  -- the service has one (DeepSeek's comes first and goes along with the question)
  function M.ask(prompt, label)
    if chat.waiting then E.note('still waiting for the answer'); return end
    local c = chat
    local a = E.article() or {}
    local j, jerr = J()
    if not j then E.note(jerr); return end
    local web = web and A.web_ok(cfg)
    j.web = web and not A.web_first(cfg)
    c.msgs[#c.msgs + 1] = { role = 'user', text = prompt, label = (label or prompt) .. (web and ' (web search)' or '') }
    local name = A.prov(cfg).name
    local function fail(why)
      c.waiting = false
      if #c.msgs > 0 and c.msgs[#c.msgs].role == 'user' then table.remove(c.msgs) end   -- it can be asked again
      E.note('AI: ' .. E.short(why or 'no answer', 60))
      if c ~= chat then return end
      if #c.msgs == 0 and E.get_screen() == 'chat' then E.set_screen('aimenu') end
      M.layout(false)
    end
    local function send()
      local opts, err = A.request(cfg, { title = a.title, feed = a.feed, date = a.date, url = a.url, text = a.text, what = E.what }, c.msgs, j)
      if not opts then fail(err); return end
      c.waiting = 'Asking ' .. name .. (j.web and ', searching the web…' or '…')
      if c == chat then M.layout(true) end
      E.submit(opts, 'asking ' .. name .. '…', 60000, function(resp, nerr)
        local text, why
        if nerr then why = nerr else text, why = A.answer(cfg, resp, dec) end
        if not text then fail(why); return end
        c.waiting = false
        c.msgs[#c.msgs + 1] = { role = 'assistant', text = text }
        E.note('')
        if c == chat then M.layout(true) end
      end)
    end
    E.set_screen('chat')
    E.keep_wifi()
    if web and A.web_first(cfg) then
      -- DeepSeek: the model writes the search query, the app searches, the results go with the question
      local art = { title = a.title, feed = a.feed, date = a.date, url = a.url, text = a.text, what = E.what }   -- as send() gives it
      local function search(query)
        local opts, err = A.search_request(cfg, query, enc, prompt)
        if not opts then fail(err); return end
        c.waiting = 'Searching the web…'
        if c == chat then M.layout(true) end
        E.submit(opts, 'searching the web…', 30000, function(resp, nerr)
          local found, why
          if nerr then why = nerr else found, why = A.search_text(resp, dec) end
          if not found then fail(why); return end
          c.msgs[#c.msgs].text = prompt .. '\n\n' .. found
          send()
        end)
      end
      local qopts = A.query_request(cfg, art, c.msgs, j)
      c.waiting = 'Choosing what to search…'
      M.layout(true)
      if not qopts then search(A.query_text(cfg, nil, dec, art, prompt)); return end
      E.submit(qopts, 'choosing what to search…', 30000, function(resp, nerr)
        search(A.query_text(cfg, not nerr and resp or nil, dec, art, prompt))
      end)
    else
      c.waiting = true
      M.layout(true)
      send()
    end
  end

  -- your own question
  function M.ask_own()
    local ok, e = pcall(function()
      local title = (#chat.msgs > 0 and 'Ask more' or 'Ask about this article') .. ((web and A.web_ok(cfg)) and ' (with a web search)' or '')
      ctx.input:text({ title = title, text = '', max_bytes = 256 }, function(c, v)
        if type(v) == 'string' and v:match('%S') then M.ask((v:gsub('^%s+', ''):gsub('%s+$', ''))) end
        E.refresh()
      end)
    end)
    if not ok then E.note('edit ! ' .. E.short(e, 30)) end
  end

  local function items() return A.items(cfg, #chat.msgs > 0, nil, nil, web) end
  function M.web() return web end

  -- the connection test on the AI page: a one-word question, the answer in the status line
  function M.test()
    local j, jerr = J()
    if not j then E.note(jerr); return end
    local opts, err = A.request(cfg, A.TEST_ART, A.TEST_MSGS, j)
    if not opts then E.note('AI: ' .. tostring(err)); return end
    E.keep_wifi()
    E.submit(opts, 'testing ' .. A.prov(cfg).name .. '…', 60000, function(resp, nerr)
      local text, why
      if nerr then why = nerr else text, why = A.answer(cfg, resp, dec) end
      E.note(text and ('works: "' .. E.short(text, 30) .. '"') or ('AI: ' .. E.short(why or 'no answer', 60)))
    end)
  end

  -- ai.txt in the app's folder (USB): its settings are taken in and the file is deleted, so a
  -- long key need not be typed and does not stay on the card
  function M.import()
    local ok, s = pcall(function()
      if not (ctx.files and ctx.files:exists('ai.txt')) then return nil end
      return ctx.files:read('ai.txt', 0, 4096)
    end)
    if not (ok and A.take(cfg, s)) then return false end
    E.save()
    pcall(function() ctx.files:remove('ai.txt') end)
    E.note('AI settings taken from ai.txt (file deleted)')
    return true
  end

  -- Settings' AI cell: its value, and what a tap on it does
  function M.value() return M.on() and A.prov(cfg).name or (cfg.aion and 'not set up yet' or 'off') end
  function M.open_settings() M.import(); A.buttons(true); E.set_screen('aiset') end

  -- My buttons: a tap edits one as "Label | question" (emptied: deleted); Add a button adds one
  function M.edit_button(i)
    local list = {}
    for k, b in ipairs(A.buttons()) do list[k] = b end
    local cur = list[i]
    local ok, err = pcall(function()
      ctx.input:text({ title = cur and 'Label | question (empty: delete)' or 'New button: Label | question', text = cur and (cur.label .. ' | ' .. cur.q) or '',
                       max_bytes = 256 }, function(c, v)
        if type(v) == 'string' then
          local b = A.parse_button(v)
          if cur and not b then table.remove(list, i)
          elseif b and cur then list[i] = b
          elseif b and #list < A.BUTTONS_MAX then list[#list + 1] = b end
          if b or cur then
            local saved = A.save_buttons(list)
            if not saved then E.note('could not write ' .. A.BUTTONS_FILE) end
          end
        end
        E.refresh()
      end)
    end)
    if not ok then E.note('edit ! ' .. E.short(err, 30)) end
  end

  function M.edit(i)
    local s = A.SET[i]
    if not s then return end
    local k = s[1]
    if k == 'aion' then local m = A.toggle(cfg); E.save(); if m then E.note(m) end; return end
    if k == 'aiprov' then E.set_screen('aiprov'); return end
    if k == 'aitest' then M.test(); return end
    if k == 'aibtn' then A.buttons(true); E.set_screen('aibtns'); return end
    local title, start = A.field(cfg, k)
    local ok, err = pcall(function()
      ctx.input:text({ title = title, text = start, max_bytes = 256 }, function(c, v)
        if type(v) == 'string' then
          local stored, why = A.store(cfg, k, v, dec)
          if stored then E.save() else E.note(why) end
        end
        E.refresh()
      end)
    end)
    if not ok then E.note('edit ! ' .. E.short(err, 30)) end
  end

  -- the Service list: Ollama and Other ask for their address at once
  function M.choose(id)
    local need = A.choose(cfg, id)
    E.save()
    E.set_screen('aiset')
    if need then for i, s in ipairs(A.SET) do if s[1] == 'aiurl' then M.edit(i) end end end
  end

  ---------------------------------------------------------------- layout

  -- the AI page's cells: in portrait a short one shares its row with the next short one; in
  -- landscape every cell is a half; { x, row, w } each and the rows used
  local function grid()
    local W, H = E.dims()
    local out, row, col = {}, 0, 0
    local n = W > H and 3 or 2                     -- landscape: three columns
    local cw = (W - 32 - (n - 1) * 16) // n
    for i, s in ipairs(A.SET) do
      if W > H or A.HALF[s[1]] then
        if col == n then row, col = row + 1, 0 end
        out[i] = { 16 + col * (cw + 16), row, cw }
        col = col + 1
      else
        if col > 0 then row, col = row + 1, 0 end
        out[i] = { 16, row, W - 32 }
        row = row + 1
      end
    end
    return out, row + (col > 0 and 1 or 0)
  end
  local function set_rect(i)
    local _, _, TOP = E.dims()
    local r = grid()[i]
    return r[1], TOP + 20 + r[2] * 96, r[3], 96
  end
  local function prov_rect(i) local _, _, TOP = E.dims(); return E.cell(i, TOP + 16, 64, 54) end
  -- the ready questions: two a row (three in landscape), then your question, the web search and
  -- Start over in a new row of the same cells
  local function menu_cells()
    local W, H, TOP = E.dims()
    local n = W > H and 3 or 2
    local rh = W > H and 50 or 64
    local cw = (W - 32 - (n - 1) * 12) // n
    local out, col, y, prev = {}, 0, W > H and TOP + 50 or TOP + 80, nil
    for _, it in ipairs(items()) do
      if it[2] == 'web' then                        -- the switch, across the top
        out[#out + 1] = { x = 16, y = y, w = W - 32, h = rh - 10, item = it }; y = y + rh
      else
        local group = it[2] == 'ask' and 'ask' or 'tail'
        if prev and group ~= prev and col > 0 then col, y = 0, y + rh end
        out[#out + 1] = { x = 16 + col * (cw + 12), y = y, w = cw, h = rh - 10, item = it }
        col = col + 1
        if col == n then col, y = 0, y + rh end
        prev = group
      end
    end
    return out
  end
  local function btn_rect(i) local _, _, TOP = E.dims(); return E.cell(i, TOP + 56, 70, 58) end

  ---------------------------------------------------------------- drawing

  local function draw_set(gg)
    local W, H, TOP = E.dims()
    local f = F()
    E.bar(gg, { 'Back' })
    for i, s in ipairs(A.SET) do
      local x, y, w = set_rect(i)
      gg:text(x, y, E.fit(s[2], f and f.small, w), { font = f and f.small })
      gg:rect(x, y + 24, w, 48)
      gg:text(x + 12, y + 36, E.fit(A.value(cfg, s[1]), f and f.medium, w - 24), { font = f and f.medium })
    end
    if W <= H then
      local _, rows = grid()
      local y = TOP + 20 + rows * 96
      local path = (ctx.files and type(ctx.files.path) == 'string' and ctx.files.path ~= '') and ctx.files.path or E.folder
      for _, l in ipairs({ 'Off: no AI button anywhere. On: one in articles.', 'A long key: put ai.txt in ' .. path .. '/',
        'with lines service=deepseek, key=..., model=...;', 'the app takes it in and deletes the file.' }) do
        gg:text(16, y, l, { font = f and f.small }); y = y + 22
      end
    end
    E.draw_status(gg)
  end

  local function draw_prov(gg)
    local f = F()
    E.bar(gg, { 'Back' })
    local cur = A.prov(cfg).id
    for i, P in ipairs(A.PROVIDERS) do
      local x, y, w, h = prov_rect(i)
      gg:rect(x, y, w, h)
      if P.id == cur then gg:rect(x + 3, y + 3, w - 6, h - 6) end
      gg:text(x + 20, y + 14, E.fit(P.label, f and f.medium, w - 40), { font = f and f.medium })
    end
    E.draw_status(gg)
  end

  local function draw_menu(gg)
    local W, H, TOP = E.dims()
    local f = F()
    local a = E.article()
    E.bar(gg, { 'Back' })
    gg:text(16, TOP + 10, 'Ask ' .. A.prov(cfg).name, { font = f and f.large })
    if W <= H then gg:text(16, TOP + 46, E.fit(a and a.title or '', f and f.small, W - 32), { font = f and f.small }) end
    for _, c in ipairs(menu_cells()) do
      gg:rect(c.x, c.y, c.w, c.h)
      if c.item[2] == 'web' and web then gg:rect(c.x + 3, c.y + 3, c.w - 6, c.h - 6) end   -- on: a double frame
      gg:text(c.x + 12, c.y + (c.h - 24) // 2, E.fit(c.item[1], f and f.medium, c.w - 24), { font = f and f.medium })
    end
    E.draw_status(gg)
  end

  local function draw_btns(gg)
    local W, H, TOP = E.dims()
    local f = F()
    E.bar(gg, { 'Back' })
    gg:text(16, TOP + 10, 'My buttons', { font = f and f.large })
    local list = A.buttons()
    local n = #list + (#list < A.BUTTONS_MAX and 1 or 0)
    for i = 1, n do
      local x, y, w, h = btn_rect(i)
      gg:rect(x, y, w, h)
      local b = list[i]
      if b then
        gg:text(x + 12, y + 6, E.fit(b.label, f and f.medium, w - 24), { font = f and f.medium })
        gg:text(x + 12, y + 32, E.fit(b.q, f and f.small, w - 24), { font = f and f.small })
      else
        gg:text(x + 12, y + 16, 'Add a button', { font = f and f.medium })
      end
    end
    if W <= H then
      local _, y = btn_rect(n + 1)
      local path = (ctx.files and type(ctx.files.path) == 'string' and ctx.files.path ~= '') and ctx.files.path or E.folder
      for _, l in ipairs({ 'They come after the ready questions. Tap one to', 'change it; empty it to delete it. Also in',
        path .. '/' .. A.BUTTONS_FILE .. ' (USB):', 'one "Label | question" a line.' }) do
        gg:text(16, y + 4, l, { font = f and f.small }); y = y + 22
      end
    end
    E.draw_status(gg)
  end

  local function draw_chat(gg)
    local W, H, TOP = E.dims()
    local f = F()
    E.bar(gg, A.chat_bar(cfg))
    local first = chat.starts[chat.page] or 1
    local last = chat.starts[chat.page + 1] and (chat.starts[chat.page + 1] - 1) or #chat.lines
    local y = TOP + 4
    for i = first, last do
      local ln = chat.lines[i]
      if not ln then break end
      if ln.rule then gg:line(12, y + 2, W - 12, y + 2)
      elseif ln.s ~= '' then gg:text(12 + ln.x, y, ln.s, { font = f and f[ln.f] }) end
      y = y + ln.h
    end
    if chat.pages > 1 and (E.status() or '') == '' and not E.busy() then
      gg:text(W - 70, H - 26, chat.page .. '/' .. chat.pages, { font = f and f.small })
    end
    E.draw_status(gg)
  end

  function M.draw(gg)
    local s = E.get_screen()
    if s == 'aiset' then draw_set(gg)
    elseif s == 'aiprov' then draw_prov(gg)
    elseif s == 'aimenu' then draw_menu(gg)
    elseif s == 'aibtns' then draw_btns(gg)
    elseif s == 'chat' then draw_chat(gg) end
  end

  ---------------------------------------------------------------- input

  function M.page(delta)
    local p = chat.page + delta
    if p >= 1 and p <= chat.pages then chat.page = p end
  end

  -- Back: the conversation and the ready questions to the article (the questions to the
  -- conversation when there is one), the AI page to Settings, the Service list to the AI page
  function M.back()
    local s = E.get_screen()
    if s == 'chat' then E.set_screen('article')
    elseif s == 'aimenu' then E.set_screen(#chat.msgs > 0 and 'chat' or 'article')
    elseif s == 'aiset' then E.set_screen('settings')
    elseif s == 'aiprov' or s == 'aibtns' then E.set_screen('aiset') end
  end

  function M.tap(x, y)
    local W = E.dims()
    local s = E.get_screen()
    if s == 'chat' then
      if y < 46 then
        local bar = A.chat_bar(cfg)
        local b = bar[E.bar_hit(x, #bar) or 0]
        if b == 'Back' then M.back() elseif b == 'Prev' then M.page(-1) elseif b == 'Next' then M.page(1)
        elseif b == 'More' then E.set_screen('aimenu') end
        return
      end
      if x < W / 3 then M.page(-1) else M.page(1) end
    elseif s == 'aimenu' then
      if y < 46 then M.back(); return end
      for _, c in ipairs(menu_cells()) do
        local m = c.item
        if x >= c.x and x < c.x + c.w and y >= c.y and y < c.y + c.h then
          if m[2] == 'ask' then M.ask(m[3], m[1])
          elseif m[2] == 'own' then M.ask_own()
          elseif m[2] == 'web' then
            web = not web
            E.note(web and 'web search on for the next questions' or 'web search off')
          elseif m[2] == 'new' then
            if chat.waiting then E.note('still waiting for the answer') else chat.msgs = {}; M.layout(false); E.note('') end
          end
          return
        end
      end
    elseif s == 'aibtns' then
      if y < 46 then M.back(); return end
      local list = A.buttons()
      for i = 1, #list + (#list < A.BUTTONS_MAX and 1 or 0) do
        local bx, by, bw, bh = btn_rect(i)
        if x >= bx and x < bx + bw and y >= by and y < by + bh then M.edit_button(i); return end
      end
    elseif s == 'aiprov' then
      if y < 46 then M.back(); return end
      for i, P in ipairs(A.PROVIDERS) do
        local px, py, pw, ph = prov_rect(i)
        if x >= px and x < px + pw and y >= py and y < py + ph then M.choose(P.id); return end
      end
    elseif s == 'aiset' then
      if y < 46 then M.back(); return end
      for i = 1, #A.SET do
        local sx, sy, sw = set_rect(i)
        if x >= sx and x < sx + sw and y >= sy + 24 and y < sy + 72 then M.edit(i); return end
      end
    end
  end

  return M
end

return U
end

__mods['feeds'] = function()
-- feeds.lua: RSS, Atom and OPML read as text, and HTML turned into the article text the layout
-- uses. No network, no screen: main.lua fetches, stores and draws.
--
--   F.parse_feed(body)          -> { title, link, items = { {id, title, link, date, summary, content} } }
--   F.is_feed(body), F.is_opml(body), F.discover(html, base) -> feed addresses a page names
--   F.parse_opml(text)          -> { title, feeds = { {title, url, site, path} } }  path: folder names, outermost first
--   F.write_opml(title, feeds)  -> the OPML text
--   F.date(s)                   -> seconds since 1970 (UTC), or nil
--   F.html_to_text(html, max, imgs, base), F.excerpt(html, n), F.absolute(src, base)
--   F.hash(s)                   -> 8 hex digits, for file names

local F = {}

------------------------------------------------------------------ text

local NAMED = { amp = '&', lt = '<', gt = '>', quot = '"', apos = "'", nbsp = ' ', ensp = ' ', emsp = ' ',
  thinsp = ' ', mdash = '\226\128\148', ndash = '\226\128\147', hellip = '\226\128\166',
  lsquo = '\226\128\152', rsquo = '\226\128\153', ldquo = '\226\128\156', rdquo = '\226\128\157',
  laquo = '\194\171', raquo = '\194\187', copy = '\194\169', reg = '\194\174', trade = '\226\132\162',
  middot = '\194\183', bull = '\226\128\162', euro = '\226\130\172', pound = '\194\163', deg = '\194\176',
  times = '\195\151', shy = '', zwj = '', zwnj = '' }

function F.decode_entities(t)
  return (t:gsub('&(#?[%w]+);', function(b)
    if b:sub(1, 1) == '#' then
      local hex = b:sub(2, 2) == 'x' or b:sub(2, 2) == 'X'
      local code = hex and tonumber(b:sub(3), 16) or tonumber(b:sub(2))
      if not code or code <= 0 or code > 0x10FFFF or (code >= 0xD800 and code <= 0xDFFF) then return '' end
      if code < 0x20 and code ~= 9 and code ~= 10 and code ~= 13 then return '' end
      if code == 0xA0 then return ' ' end
      local ok, ch = pcall(utf8.char, code)
      return ok and ch or ''
    end
    return NAMED[b] or NAMED[b:lower()]
  end))
end

function F.url_encode(s)
  return (tostring(s):gsub('[^%w%-%._~]', function(ch) return string.format('%%%02X', ch:byte()) end))
end

-- a hash of an address, as 8 hex digits (file names may only hold [a-z0-9._-]); the arithmetic
-- stays within 31 bits, so it is the same on the reader's 32-bit integers
function F.hash(s)
  local h = 5381
  for i = 1, #s do h = (h * 33 + s:byte(i)) & 0x7fffffff end
  return string.format('%08x', h)
end

function F.absolute(src, base)
  src = tostring(src or ''):gsub('^%s+', ''):gsub('%s+$', '')
  if src == '' or src:match('^data:') or src:match('^javascript:') then return nil end
  if src:match('^https?://') then return src end
  if src:sub(1, 2) == '//' then return 'https:' .. src end
  local origin = tostring(base or ''):match('^(https?://[^/]+)')
  if not origin then return nil end
  if src:sub(1, 1) == '/' then return origin .. src end
  local dir = tostring(base):match('^(https?://.*/)') or (origin .. '/')
  return dir .. src
end

-- Pictures: an article's <img> become "[[img:N]]" paragraphs and entries {n, w, h, src} in imgs,
-- src being a greyscale JPEG from the free images.weserv.nl resizer (the reader fetches it). With
-- width and height in the HTML the picture keeps that shape, fitted to the screen; without them it
-- fits a 456 x 342 box. Icons and tracking pixels are left out. (As in the wallabag app.)
local IMG_W, IMG_H, TINY_IMG, MAX_IMAGES = 456, 640, 80, 12

local function attr(tag, name)
  local v = tag:match('[%s]' .. name .. '%s*=%s*"([^"]*)"') or tag:match('[%s]' .. name .. "%s*=%s*'([^']*)'")
    or tag:match('[%s]' .. name .. '%s*=%s*([^%s>"\']+)')
  return v and F.decode_entities(v) or nil
end
F.attr = attr

local function picture(tag, base)
  local src = attr(tag, 'data%-src') or attr(tag, 'data%-original') or attr(tag, 'data%-lazy%-src')
  local plain = attr(tag, 'src')
  if not src and plain and not plain:match('^data:') then src = plain end
  if not src then
    local set = attr(tag, 'srcset') or attr(tag, 'data%-srcset')
    src = set and set:match('^%s*([^%s,]+)')
  end
  src = F.absolute(src, base)
  if not src then return nil end
  local w = tonumber((attr(tag, 'width') or ''):match('^%s*(%d+)%s*$'))
  local h = tonumber((attr(tag, 'height') or ''):match('^%s*(%d+)%s*$'))
  if (w and w <= 2) or (h and h <= 2) then return nil end
  if w and h and w <= TINY_IMG and h <= TINY_IMG then return nil end
  if w and h then
    if w > IMG_W then h = (h * IMG_W + w // 2) // w; w = IMG_W end
    if h > IMG_H then w = (w * IMG_H + h // 2) // h; h = IMG_H end
    w, h = math.max(w, 16), math.max(h, 16)
  else
    w, h = IMG_W, 342
  end
  return { w = w, h = h, src = 'https://images.weserv.nl/?url=' .. F.url_encode(src) .. '&w=' .. w .. '&h=' .. h
    .. '&fit=contain&cbg=white&output=jpg&q=70&filt=greyscale' }
end

-- HTML -> text with the markers the layout styles: paragraphs split by a blank line, "# "
-- headings, "> " quotes, "• " list items. Source line breaks are spaces, as in a browser.
local DROP = { script = true, style = true, svg = true, iframe = true, noscript = true, template = true, head = true }
local BLOCK_END = { p = true, div = true, li = true, blockquote = true, pre = true, tr = true, figure = true,
  figcaption = true, dd = true, dt = true, section = true, article = true, header = true, footer = true,
  table = true, ul = true, ol = true, h1 = true, h2 = true, h3 = true, h4 = true, h5 = true, h6 = true }

function F.html_to_text(html, max, imgs, base)
  local src = tostring(html or ''):gsub('<!%-%-.-%-%->', ' ')
  local out, i, n, skip = {}, 1, #src, nil
  while i <= n do
    local a = src:find('<', i, true)
    if not a then
      if not skip then out[#out + 1] = (src:sub(i):gsub('[\r\n\t]', ' ')) end
      break
    end
    if not skip and a > i then out[#out + 1] = (src:sub(i, a - 1):gsub('[\r\n\t]', ' ')) end
    local b = src:find('>', a, true)
    if not b then break end
    local tag = src:sub(a + 1, b - 1)
    local close, name = tag:match('^(/?)%s*([%a][%w]*)')
    name = name and name:lower()
    if skip then
      if close == '/' and name == skip then skip = nil end
    elseif name then
      if close == '' and DROP[name] and not tag:match('/%s*$') then skip = name
      elseif name == 'br' then out[#out + 1] = '\n'
      elseif close == '' and name:match('^h[1-6]$') then out[#out + 1] = '\n\n# '
      elseif close == '' and name == 'blockquote' then out[#out + 1] = '\n\n> '
      elseif close == '' and name == 'hr' then out[#out + 1] = '\n\n* * *\n\n'
      elseif close == '' and name == 'li' then out[#out + 1] = '\n\226\128\162 '
      elseif close == '' and (name == 'p' or name == 'div') then out[#out + 1] = '\n\n'
      elseif close == '' and name == 'img' and imgs and #imgs < MAX_IMAGES then
        local pic = picture(' ' .. tag:sub(4), base)
        if pic then imgs[#imgs + 1] = pic; pic.n = #imgs; out[#out + 1] = '\n\n[[img:' .. #imgs .. ']]\n\n' end
      elseif close == '/' and BLOCK_END[name] then out[#out + 1] = '\n\n' end
    end
    i = b + 1
  end
  local t = F.decode_entities(table.concat(out))
  t = t:gsub('\194\160', ' '):gsub('[ \t\f\v]+', ' '):gsub(' *\n *', '\n')
  for _ = 1, 2 do t = t:gsub('\n# *\n', '\n'):gsub('\n> *\n', '\n'):gsub('\n\226\128\162 *\n', '\n') end
  t = t:gsub('\n\n\n+', '\n\n'):gsub('^%s+', ''):gsub('%s+$', '')
  if max and #t > max then
    local cut = t:sub(1, max)
    local sp = cut:match('^.*() ')
    if sp and sp > max * 0.8 then cut = cut:sub(1, sp - 1) end
    cut = cut:gsub('[\192-\255][\128-\191]*$', '')
    t = cut .. '\226\128\166'
  end
  return t
end

-- a short plain summary: the text on one line, at most n bytes, ending on a whole character
function F.excerpt(html, n)
  local t = F.html_to_text(html or '', (n or 400) * 2):gsub('%[%[img:%d+%]%]', ''):gsub('[#>]%s', ''):gsub('%s+', ' ')
  t = t:gsub('^%s+', ''):gsub('%s+$', '')
  n = n or 400
  if #t > n then
    t = t:sub(1, n):gsub('[\192-\255][\128-\191]*$', '')
    local sp = t:match('^.*() ')
    if sp and sp > n * 0.7 then t = t:sub(1, sp - 1) end
    t = t .. '\226\128\166'
  end
  return t
end

------------------------------------------------------------------ dates

local MONTHS = { jan = 1, feb = 2, mar = 3, apr = 4, may = 5, jun = 6, jul = 7, aug = 8, sep = 9, oct = 10, nov = 11, dec = 12 }
local ZONES = { ut = 0, utc = 0, gmt = 0, z = 0, est = -300, edt = -240, cst = -360, cdt = -300, mst = -420,
  mdt = -360, pst = -480, pdt = -420, cet = 60, cest = 120, bst = 60 }

-- days since 1970-01-01 of a calendar date (Howard Hinnant's days_from_civil)
local function days(y, m, d)
  y = (m <= 2) and (y - 1) or y
  local era = (y >= 0 and y or y - 399) // 400
  local yoe = y - era * 400
  local doy = (153 * (m + (m > 2 and -3 or 9)) + 2) // 5 + d - 1
  local doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
  return era * 146097 + doe - 719468
end

local function zone_minutes(z)
  if not z or z == '' then return 0 end
  local sign, hh, mm = z:match('^([%+%-])(%d%d):?(%d%d)$')
  if sign then
    local m = tonumber(hh) * 60 + tonumber(mm)
    return sign == '-' and -m or m
  end
  return ZONES[z:lower()] or 0
end

-- RFC 822 ("Wed, 30 Oct 2026 16:00:00 +0000") or ISO 8601 ("2026-10-30T16:00:00+03:00")
function F.date(s)
  if type(s) ~= 'string' then return nil end
  s = s:gsub('^%s+', ''):gsub('%s+$', '')
  local d, mon, y, hh, mi, ss, z = s:match('(%d%d?)%s+(%a%a%a)%a*%.?%s+(%d%d%d?%d?)%s+(%d%d?):(%d%d):?(%d*)%s*([%+%-]?%w*:?%w*)')
  if d then
    local m = MONTHS[mon:lower()]
    if not m then return nil end
    y = tonumber(y); if y < 100 then y = y + 2000 end
    return days(y, m, tonumber(d)) * 86400 + tonumber(hh) * 3600 + tonumber(mi) * 60 + (tonumber(ss) or 0) - zone_minutes(z) * 60
  end
  local yy, mm, dd, rest = s:match('^(%d%d%d%d)%-(%d%d)%-(%d%d)(.*)$')
  if yy then
    local h2, m2, s2 = rest:match('^[Tt ](%d%d):(%d%d):?(%d*)')
    local zz = rest:match('([Zz])$') or rest:match('([%+%-]%d%d:?%d%d)$')
    return days(tonumber(yy), tonumber(mm), tonumber(dd)) * 86400 + (tonumber(h2) or 0) * 3600
      + (tonumber(m2) or 0) * 60 + (tonumber(s2) or 0) - zone_minutes(zz) * 60
  end
  return nil
end

-- seconds since 1970 -> "2026-10-30 16:00", shifted by the reader's offset from UTC in minutes
-- (Howard Hinnant's civil_from_days)
function F.format_date(t, offset_min)
  if not t then return '' end
  t = t + (offset_min or 0) * 60
  local z = t // 86400 + 719468
  local secs = t % 86400
  local era = (z >= 0 and z or z - 146096) // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local y = yoe + era * 400
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp + (mp < 10 and 3 or -9)
  if m <= 2 then y = y + 1 end
  return string.format('%04d-%02d-%02d %02d:%02d', y, m, d, secs // 3600, secs % 3600 // 60)
end

------------------------------------------------------------------ feeds

-- the text inside an element: CDATA unwrapped, tags kept (they are HTML), entities decoded once
local function inner(s)
  if not s then return nil end
  if s:find('<![CDATA[', 1, true) then
    s = s:gsub('<!%[CDATA%[(.-)%]%]>', function(c) return (c:gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;')) end)
  end
  return F.decode_entities(s)
end

-- the first <name ...>...</name> in block (any namespace prefix written as in the feed)
local function element(block, name)
  local _, b = block:find('<' .. name .. '[%s>]')
  if not b then return nil end
  if block:sub(b, b) ~= '>' then
    local e = block:find('>', b, true)
    if not e then return nil end
    if block:sub(e - 1, e - 1) == '/' then return '' end
    b = e
  end
  local c = block:find('</' .. name .. '%s*>', b + 1)
  if not c then return nil end
  return block:sub(b + 1, c - 1)
end

-- an element as plain text: a CDATA section is literal text ("First <post>" stays so); outside it
-- tags are markup and go, and entities are decoded
local function plain(text)
  if not text then return nil end
  local out, pos = {}, 1
  while true do
    local a, b, lit = text:find('<!%[CDATA%[(.-)%]%]>', pos)
    local markup = text:sub(pos, (a or #text + 1) - 1)
    out[#out + 1] = F.decode_entities((markup:gsub('<[^>]*>', '')))
    if not a then break end
    out[#out + 1] = lit
    pos = b + 1
  end
  local joined = table.concat(out)
  return (joined:gsub('%s+', ' '):gsub('^ ', ''):gsub(' $', ''))
end

local function atom_link(block)
  local first
  for tag in block:gmatch('<link%s[^>]*>') do
    local rel = attr(' ' .. tag:sub(6), 'rel')
    local href = attr(' ' .. tag:sub(6), 'href')
    if href then
      if not rel or rel == 'alternate' then return href end
      first = first or href
    end
  end
  return first
end

function F.is_feed(body)
  local head = (body or ''):sub(1, 2048)
  return head:find('<rss[%s>]') or head:find('<feed[%s>]') or head:find('<rdf:RDF[%s>]') or head:find('<channel[%s>]')
end
function F.is_opml(body) return (body or ''):sub(1, 2048):find('<opml[%s>]') ~= nil end

-- Only whole items count, so a feed cut short (the reader keeps 128 KB of an answer) still gives
-- its newest items. kind: 'rss' (and RSS 1.0 / RDF) or 'atom'.
function F.parse_feed(body)
  if type(body) ~= 'string' or not F.is_feed(body) then return nil, 'not a feed' end
  local atom = body:sub(1, 2048):find('<feed[%s>]') ~= nil
  local open, close = atom and '<entry[%s>]' or '<item[%s>]', atom and '</entry>' or '</item>'
  local first = body:find(open) or #body + 1
  local head = body:sub(1, first - 1)
  local feed = { title = plain(element(head, 'title')) or '', items = {} }
  feed.link = atom and atom_link(head) or plain(element(head, 'link'))
  local pos = 1
  while true do
    local a = body:find(open, pos)
    if not a then break end
    local b = body:find(close, a, true)
    if not b then break end                       -- the last one was cut off
    local block = body:sub(a, b - 1)
    pos = b + #close
    local it = { title = plain(element(block, 'title')) or '' }
    if atom then
      it.link = atom_link(block)
      it.id = plain(element(block, 'id'))
      it.date = F.date(plain(element(block, 'published')) or plain(element(block, 'updated')))
      it.summary = inner(element(block, 'summary'))
      it.content = inner(element(block, 'content'))
    else
      it.link = plain(element(block, 'link'))
      if not it.link or it.link == '' then
        local guid = block:match('<guid[^>]-isPermaLink%s*=%s*["\']true["\'][^>]*>(.-)</guid>')
        it.link = plain(guid)
      end
      it.id = plain(element(block, 'guid'))
      it.date = F.date(plain(element(block, 'pubDate')) or plain(element(block, 'dc:date')))
      it.summary = inner(element(block, 'description'))
      it.content = inner(element(block, 'content:encoded'))
    end
    if it.link then it.link = F.absolute(it.link, feed.link) or it.link end
    if not it.id or it.id == '' then it.id = it.link or it.title end
    if it.id and it.id ~= '' then feed.items[#feed.items + 1] = it end
  end
  return feed
end

-- feed addresses named by a page's <link rel="alternate" type="application/rss+xml" ...>
function F.discover(html, base)
  local out = {}
  for tag in tostring(html or ''):sub(1, 131072):gmatch('<link%s[^>]*>') do
    local t = ' ' .. tag:sub(6)
    local rel, ty, href = (attr(t, 'rel') or ''):lower(), (attr(t, 'type') or ''):lower(), attr(t, 'href')
    if href and rel:find('alternate', 1, true) and (ty:find('rss', 1, true) or ty:find('atom', 1, true)) then
      local u = F.absolute(href, base)
      if u then out[#out + 1] = { url = u, title = attr(t, 'title') } end
    end
  end
  return out
end

------------------------------------------------------------------ OPML

function F.parse_opml(text)
  text = tostring(text or '')
  local out = { title = plain(element(text, 'title')) or '', feeds = {} }
  local open = {}                -- the outlines around this one: a folder name, or false for a feed
  local pos = 1
  local function path()
    local p = {}
    for _, n in ipairs(open) do if n then p[#p + 1] = n end end
    return p
  end
  while true do
    local a, b, tag = text:find('<(/?outline[^>]*)>', pos)
    if not a then break end
    pos = b + 1
    if tag:sub(1, 1) == '/' then
      table.remove(open)
    else
      local t = ' ' .. tag:sub(8)
      local url = attr(t, 'xmlUrl') or attr(t, 'xmlurl')
      local name = attr(t, 'title') or attr(t, 'text') or ''
      if url then
        out.feeds[#out.feeds + 1] = { title = name ~= '' and name or url, url = url, site = attr(t, 'htmlUrl'), path = path() }
      end
      if not tag:match('/%s*$') then open[#open + 1] = (not url) and name or false end
    end
  end
  return out
end

local function xml(s)
  return (tostring(s or ''):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'):gsub('"', '&quot;'))
end

-- folders kept, nested as in f.path: a folder's feeds first, then its folders, in the order met
function F.write_opml(title, feeds)
  local out = { '<?xml version="1.0" encoding="UTF-8"?>', '<opml version="2.0">', '  <head>',
    '    <title>' .. xml(title) .. '</title>', '  </head>', '  <body>' }
  local root = { feeds = {}, kids = {}, by = {} }
  for _, f in ipairs(feeds) do
    local node = root
    for _, name in ipairs(f.path or {}) do
      if not node.by[name] then
        local k = { name = name, feeds = {}, kids = {}, by = {} }
        node.by[name] = k; node.kids[#node.kids + 1] = k
      end
      node = node.by[name]
    end
    node.feeds[#node.feeds + 1] = f
  end
  local function put(node, ind)
    for _, f in ipairs(node.feeds) do
      out[#out + 1] = ind .. '<outline type="rss" text="' .. xml(f.title) .. '" title="' .. xml(f.title) .. '" xmlUrl="' .. xml(f.url) .. '"'
        .. (f.site and f.site ~= '' and (' htmlUrl="' .. xml(f.site) .. '"') or '') .. '/>'
    end
    for _, k in ipairs(node.kids) do
      out[#out + 1] = ind .. '<outline text="' .. xml(k.name) .. '" title="' .. xml(k.name) .. '">'
      put(k, ind .. '  ')
      out[#out + 1] = ind .. '</outline>'
    end
  end
  put(root, '    ')
  out[#out + 1] = '  </body>'
  out[#out + 1] = '</opml>'
  return table.concat(out, '\n') .. '\n'
end

return F
end

__mods['library'] = function()
-- library.lua: feeds on the reader. Collections are OPML files in the app's folder on the card
-- (ctx.files: AppFiles/<app_id>/, "My feeds.opml" first); each feed's articles are kept in the
-- app's private files. Fetching goes through main.lua's request queue (init).
--
--   L.init{ submit, worker, has_worker }   submit(opts, label, timeout, cb); worker(path, cb, label)
--   L.collections()                  -> { {file, title} }, "My feeds" first
--   L.collection(file)               -> { file, title, feeds = { {title, url, site, path} } }
--   L.add_feed(url, title, site, file) -> true | nil, 'already' (default: into My feeds)
--   L.remove_feed(coll, url), L.save_collection(file, title, feeds)
--   L.items(coll, kind, url)         -> rows for a list (kind: unread / all / starred / feed)
--   L.info(url) -> { u = unread, e = failed last time }   from one index file, no per-feed reads
--   L.mark(row, field, value), L.content(row) -> HTML or nil
--   L.refresh(coll, force, on_feed, on_done)   fetches feeds older than FRESH_SEC one by one
-- A collection can hold hundreds of feeds (an OPML exported from another reader), so nothing
-- here reads every feed's file at once: lists are per feed, and only a few feeds stay in memory.
--   L.probe(address, cb)             cb(kind, data): 'feed' {url, title} | 'opml' {title, text} | nil, why

local F = require('feeds')
local L = {}

local KEEP_ITEMS = 40          -- articles kept per feed (starred ones are kept as well)
local KEEP_HTML = 12           -- of them, the newest with text keep their HTML for reading offline
local HTML_BYTES = 200000      -- a feed's HTML file stays under the 256 KB file limit
local FRESH_SEC = 30 * 60      -- a feed checked less than this long ago is not asked again
local EXCERPT = 300
local MY = 'My feeds.opml'

local env = {}
function L.init(e) env = e end
function L.has_worker() return env.has_worker ~= nil and env.has_worker() end

local function now_s()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if ok and type(t) == 'table' and t.valid ~= false and tonumber(t.epoch_sec) then return tonumber(t.epoch_sec) end
  return 0
end

local function sread(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
local function swrite(name, s) pcall(function() ctx.storage:write(name, s) end) end
local function sremove(name) pcall(function() ctx.storage:remove(name) end) end
local function decode(s)
  if not s then return nil end
  local ok, d = pcall(function() return ctx.json:decode(s) end)
  return (ok and type(d) == 'table') and d or nil
end
local function encode(t)
  local ok, s = pcall(function() return ctx.json:encode(t) end)
  return ok and s or nil
end

------------------------------------------------------------------ collections (OPML files)

local function files_list()
  local ok, t = pcall(function() return ctx.files:list() end)
  local out = {}
  for _, f in ipairs((ok and type(t) == 'table') and t or {}) do
    local n = type(f) == 'table' and f.name or f
    if type(n) == 'string' and n:lower():match('%.opml$') then out[#out + 1] = n end
  end
  return out
end

local function file_read(name)
  local F2 = ctx.files
  if not F2 then return nil end
  local ok, t = pcall(function()
    local parts, off = {}, 0
    for _ = 1, 8 do
      local piece = F2:read(name, off, 65536)
      if type(piece) ~= 'string' or piece == '' then break end
      parts[#parts + 1] = piece
      off = off + #piece
      if #piece < 65536 then break end
    end
    return table.concat(parts)
  end)
  return (ok and type(t) == 'string' and t ~= '') and t or nil
end

local colls = {}               -- file -> parsed collection

-- My feeds is always there, empty until a feed is added (its file is written then)
function L.collections()
  local out, mine = {}, false
  for _, n in ipairs(files_list()) do
    local c = L.collection(n)
    if c then out[#out + 1] = { file = n, title = c.title }; mine = mine or n == MY end
  end
  if not mine then out[#out + 1] = { file = MY, title = L.collection(MY).title } end
  table.sort(out, function(a, b)
    if (a.file == MY) ~= (b.file == MY) then return a.file == MY end
    return a.title:lower() < b.title:lower()
  end)
  return out
end

function L.collection(file)
  local c = colls[file]
  if c then return c end
  local text = file_read(file)
  if not text then
    if file ~= MY then return nil end
    c = { file = MY, title = 'My feeds', feeds = {} }
    colls[file] = c
    return c
  end
  local o = F.parse_opml(text)
  local title = o.title ~= '' and o.title or file:gsub('%.[Oo][Pp][Mm][Ll]$', '')
  c = { file = file, title = title, feeds = o.feeds }
  colls[file] = c
  return c
end

function L.forget() colls = {} end

function L.save_collection(file, title, feeds)
  local ok, err = pcall(function() return ctx.files:write(file, F.write_opml(title, feeds)) end)
  colls[file] = nil
  return ok and err ~= nil, (not ok) and err or nil
end

-- a name the card accepts for a collection's file
function L.file_name(title)
  local n = tostring(title or ''):gsub('[%c/\\:%*%?"<>|~]', ' '):gsub('%s+', ' '):gsub('^[%s%.]+', ''):gsub('[%s%.]+$', '')
  if n == '' then n = 'Feeds' end
  return n:sub(1, 60) .. '.opml'
end

-- into the collection file (default My feeds)
function L.add_feed(url, title, site, file)
  file = file or MY
  local c = L.collection(file)
  if not c then return nil, 'no collection' end
  for _, f in ipairs(c.feeds) do if f.url == url then return nil, 'already' end end
  local feeds = {}
  for _, f in ipairs(c.feeds) do feeds[#feeds + 1] = f end
  feeds[#feeds + 1] = { title = title ~= '' and title or url, url = url, site = site }
  L.save_collection(file, c.title, feeds)
  return true
end

function L.has_feed(url, file)
  local c = L.collection(file or MY)
  for _, f in ipairs(c and c.feeds or {}) do if f.url == url then return true end end
  return false
end

function L.remove_feed(coll, url)
  local feeds = {}
  for _, f in ipairs(coll.feeds) do if f.url ~= url then feeds[#feeds + 1] = f end end
  L.save_collection(coll.file, coll.title, feeds)
end

------------------------------------------------------------------ a feed's articles

-- f_<hash>.txt: { url, title, etag, lastmod, checked, items = { {id, t, l, d, x, r, s, c, w} } }
-- t title, l link, d date (s since 1970), x excerpt, r read, s starred, c has text to read,
-- w came through the Worker. h_<hash>.txt: { [id] = HTML } for the newest ones with text.
local CACHED = 6               -- feed records kept in memory, the most recently used
local cache, used = {}, {}     -- url -> feed record; urls, the most recent last

local function fname(url) return 'f_' .. F.hash(url) .. '.txt' end
local function hname(url) return 'h_' .. F.hash(url) .. '.txt' end

local function touch(url)
  for i, u in ipairs(used) do if u == url then table.remove(used, i); break end end
  used[#used + 1] = url
  while #used > CACHED do cache[table.remove(used, 1)] = nil end
end

function L.feed(url)
  local r = cache[url]
  if not r then
    r = decode(sread(fname(url)))
    if not r or r.url ~= url then r = { url = url, items = {} } end
    r.items = r.items or {}
    cache[url] = r
  end
  touch(url)
  return r
end

-- idx.txt: { [url] = { u = unread articles, e = 1 when the last fetch failed } }, for the feeds screen
local idx = nil
local function index()
  if not idx then idx = decode(sread('idx.txt')) or {} end
  return idx
end
function L.info(url) return index()[url] or {} end

local function note(r)
  local n = 0
  for _, it in ipairs(r.items) do if not it.r then n = n + 1 end end
  local e = r.error and 1 or nil
  local old = index()[r.url]
  if old and old.u == n and old.e == e then return end
  idx[r.url] = { u = n, e = e }
  local s = encode(idx)
  if s then swrite('idx.txt', s) end
end

local function save_feed(r)
  local s = encode(r)
  if s then swrite(fname(r.url), s) end
  note(r)
end

-- the newest first; undated articles keep the feed's order after the dated ones they came with
local function by_date(a, b) return (a.d or 0) > (b.d or 0) end

-- a parsed feed into the record: read and starred marks kept, the newest KEEP_ITEMS (and every
-- starred one) kept, the HTML of the newest with text stored for reading
local function merge(r, feed, via_worker)
  local old = {}
  for _, it in ipairs(r.items) do old[it.id] = it end
  local now = now_s()
  local seen, items, html = {}, {}, {}
  for k, it in ipairs(feed.items) do
    local id = tostring(it.id)
    if not seen[id] then
      seen[id] = true
      local prev = old[id]
      local text = it.content and it.content ~= '' and it.content or nil
      local summary = it.summary or ''
      if not text and #summary > 1500 then text = summary end     -- a long summary is the article
      local row = {
        id = id, t = it.title ~= '' and it.title or (it.link or ''), l = it.link,
        d = it.date or (prev and prev.d) or (now - k), x = it.excerpt or F.excerpt((summary ~= '' and summary or (text or '')):sub(1, 4000), EXCERPT),
        r = prev and prev.r or false, s = prev and prev.s or false,
        c = (text ~= nil) or (it.has_content and true or false), w = via_worker or nil,
      }
      items[#items + 1] = row
      if text then html[id] = text end
    end
  end
  for _, it in ipairs(r.items) do                 -- starred ones the feed no longer lists stay
    if it.s and not seen[it.id] then items[#items + 1] = it end
  end
  table.sort(items, by_date)
  local kept = {}
  for _, it in ipairs(items) do
    if #kept < KEEP_ITEMS or it.s then kept[#kept + 1] = it end
  end
  r.items = kept
  r.title = (feed.title and feed.title ~= '') and feed.title or r.title
  r.site = feed.link or r.site
  -- the HTML file: what was stored before, then the new texts, newest first, within the budget
  local store = decode(sread(hname(r.url))) or {}
  for id, h in pairs(html) do store[id] = h end
  local keep, size, n = {}, 0, 0
  for _, it in ipairs(kept) do
    local h = store[it.id]
    if h and n < KEEP_HTML and size + #h <= HTML_BYTES then keep[it.id] = h; size = size + #h; n = n + 1 end
  end
  local s = encode(keep)
  if s then swrite(hname(r.url), s) end
  save_feed(r)
end

function L.content(row)
  local store = decode(sread(hname(row.feed_url)))
  return store and store[row.id] or nil
end

function L.mark(row, field, value)
  local r = L.feed(row.feed_url)
  for _, it in ipairs(r.items) do
    if it.id == row.id then it[field] = value end
  end
  row[field == 'r' and 'read' or 'starred'] = value
  save_feed(r)
end


-- list rows in the shape the screens use (title, feed, read, starred, excerpt ...)
function L.items(coll, kind, url)
  local rows = {}
  for _, f in ipairs(coll.feeds) do
    if kind ~= 'feed' or f.url == url then
      local r = L.feed(f.url)
      local name = (f.title and f.title ~= '' and f.title ~= f.url) and f.title or (r.title or f.url)
      for _, it in ipairs(r.items) do
        if kind == 'all' or kind == 'feed' or (kind == 'unread' and not it.r) or (kind == 'starred' and it.s) then
          rows[#rows + 1] = { id = it.id, title = it.t, feed = name, d = it.d, read = it.r, starred = it.s,
            excerpt = it.x, url = it.l, has_text = it.c, via_worker = it.w, feed_url = f.url, ['local'] = true }
        end
      end
    end
  end
  table.sort(rows, by_date)
  return rows
end

------------------------------------------------------------------ fetching

local FEED_ACCEPT = 'application/rss+xml, application/atom+xml, application/xml;q=0.9, text/xml;q=0.9, */*;q=0.5'
local UA = 'Mozilla/5.0 (Xteink RSS mini app)'
local LIMIT = 131072

local gz_ok = nil
local function gunzip(b)
  local z = ctx.zlib
  if not z then return nil end
  local ok, t = pcall(function() return z:decompress(b, { format = 'gzip' }) end)
  return (ok and type(t) == 'string') and t or nil
end
local function gzip_works()
  if gz_ok == nil then
    gz_ok = ctx.zlib ~= nil and gunzip('\31\139\8\0\0\0\0\0\0\3\203\72\205\201\201\7\0\134\166\16\54\5\0\0\0') == 'hello'
  end
  return gz_ok
end

local function extend() pcall(function() ctx.budget:extend() end) end

-- one GET, redirects followed (the host leaves them to the app): cb(resp, final_url) or cb(nil, why)
local function get(url, headers, label, cb, hops)
  hops = hops or 0
  env.submit({ url = url, method = 'GET', headers = headers }, label, 30000, function(resp, err)
    if err then cb(nil, err); return end
    if type(resp) ~= 'table' then cb(nil, 'no response'); return end
    local st = tonumber(resp.status) or tonumber(resp.code) or 0
    local h = type(resp.headers) == 'table' and resp.headers or {}
    if st >= 300 and st < 400 and st ~= 304 and h.location and hops < 4 then
      local nxt = F.absolute(h.location, url)
      if nxt then get(nxt, headers, label, cb, hops + 1); return end
    end
    cb(resp, url)
  end)
end

local function body_of(resp)
  local b = type(resp.body) == 'string' and resp.body or ''
  local cut = (tonumber(resp.bytes) or #b) > #b or resp.error == 'limit_exceeded' or resp.err == 'limit_exceeded'
  if b:sub(1, 2) == '\31\139' then
    if cut then return nil, true, true end           -- a gzip answer cut short cannot be unpacked
    local t = gunzip(b)
    if not t then return nil, false, true end
    return t, false
  end
  return b, cut
end

-- the feed through the Worker (/api/feed): the newest articles of a feed of any size
local function via_worker(r, label, cb)
  if not L.has_worker() then cb(nil, 'feed too large for the reader'); return end
  env.worker('/api/feed?n=' .. KEEP_ITEMS .. '&url=' .. F.url_encode(r.url), function(data, err)
    if not data then cb(nil, err); return end
    local feed = { title = data.title, link = data.link, items = {} }
    for _, it in ipairs(type(data.items) == 'table' and data.items or {}) do
      feed.items[#feed.items + 1] = { id = it.id, title = it.title or '', link = it.link, date = tonumber(it.date) or F.date(it.date),
        excerpt = it.excerpt, has_content = it.has_content }
    end
    extend()
    merge(r, feed, true)
    cb(true)
  end, label)
end

-- the rest of a feed cut short, by byte ranges where the server allows them (up to 4 pieces)
local function more_by_range(url, text, label, cb, n)
  n = n or 1
  if n > 3 then cb(text); return end
  local from = #text
  get(url, { ['Accept'] = FEED_ACCEPT, ['User-Agent'] = UA, ['Range'] = 'bytes=' .. from .. '-' .. (from + LIMIT - 1) }, label, function(resp)
    if not resp or tonumber(resp.status) ~= 206 or type(resp.body) ~= 'string' or resp.body == '' then cb(text); return end
    local piece = resp.body
    local cut = (tonumber(resp.bytes) or #piece) > #piece
    text = text .. piece
    local h = type(resp.headers) == 'table' and resp.headers or {}
    local total = tonumber(tostring(h['content-range'] or ''):match('/(%d+)$'))
    if total and #text >= total then cb(text); return end
    if cut or #piece >= LIMIT then more_by_range(url, text, label, cb, n + 1) else cb(text) end
  end)
end

-- one feed: cb(true) changed, cb('same') not changed, cb(nil, why)
local function fetch_feed(r, label, cb)
  local h = { ['Accept'] = FEED_ACCEPT, ['User-Agent'] = UA }
  local gz = gzip_works()
  if gz then h['Accept-Encoding'] = 'gzip' end
  if r.etag then h['If-None-Match'] = r.etag end
  if r.lastmod then h['If-Modified-Since'] = r.lastmod end
  get(r.url, h, label, function(resp, final)
    extend()
    if not resp then cb(nil, final); return end
    local st = tonumber(resp.status) or tonumber(resp.code) or 0
    r.checked = now_s()
    if st == 304 then save_feed(r); cb('same'); return end
    if st >= 400 or st == 0 then save_feed(r); cb(nil, 'HTTP ' .. st); return end
    local hh = type(resp.headers) == 'table' and resp.headers or {}
    local text, cut, gzbad = body_of(resp)
    local function finish(t)
      extend()
      local feed = F.parse_feed(t or '')
      if not feed then save_feed(r); cb(nil, 'not a feed'); return end
      r.etag, r.lastmod = hh.etag, hh['last-modified']
      merge(r, feed)
      cb(true)
    end
    if text and not cut then finish(text); return end
    -- too large: the Worker if there is one, else as much as the reader can take
    if L.has_worker() then via_worker(r, label, cb); return end
    if gzbad then
      get(final, { ['Accept'] = FEED_ACCEPT, ['User-Agent'] = UA }, label, function(resp2)
        if not resp2 or type(resp2.body) ~= 'string' then cb(nil, 'feed too large'); return end
        local t2 = resp2.body
        local h2 = type(resp2.headers) == 'table' and resp2.headers or {}
        if (tonumber(resp2.bytes) or #t2) > #t2 and tostring(h2['accept-ranges'] or ''):find('bytes', 1, true) then
          more_by_range(final, t2, label, finish)
        else
          finish(t2)
        end
      end)
      return
    end
    if tostring(hh['accept-ranges'] or ''):find('bytes', 1, true) then more_by_range(final, text, label, finish) else finish(text) end
  end)
end

-- the collection's feeds, one after another (the reader carries one request at a time)
function L.refresh(coll, force, on_feed, on_done)
  local todo = {}
  local now = now_s()
  for _, f in ipairs(coll.feeds) do
    local r = L.feed(f.url)
    if force or not r.checked or now - r.checked > FRESH_SEC or now == 0 then todo[#todo + 1] = r end
  end
  local i, changed, failed = 0, 0, 0
  local function step()
    i = i + 1
    local r = todo[i]
    if not r then if on_done then on_done(changed, failed, #todo) end; return end
    fetch_feed(r, 'updating ' .. i .. '/' .. #todo, function(ok, why)
      if ok == true then changed = changed + 1 elseif not ok then failed = failed + 1; r.error = why end
      if ok then r.error = nil end
      note(r)
      if on_feed then on_feed(r, i, #todo) end
      step()
    end)
  end
  step()
end

------------------------------------------------------------------ an address typed in

local function looks_html(b) return b:sub(1, 2048):lower():find('<html', 1, true) ~= nil end

-- a site or a feed or an OPML: cb('feed', {url, title}) | cb('opml', {title, text}) | cb(nil, why)
function L.probe(address, cb)
  local url = tostring(address or ''):gsub('^%s+', ''):gsub('%s+$', '')
  if url == '' then cb(nil, 'no address'); return end
  if not url:match('^https?://') then url = 'https://' .. url end
  local h = { ['Accept'] = FEED_ACCEPT .. ', text/html;q=0.8, text/x-opml', ['User-Agent'] = UA }
  if gzip_works() then h['Accept-Encoding'] = 'gzip' end
  local tried = {}
  local function try_guess(base, list, k)
    k = k or 1
    local path = list[k]
    if not path then cb(nil, 'no feed found on this site'); return end
    local u = F.absolute(path, base)
    if not u or tried[u] then try_guess(base, list, k + 1); return end
    tried[u] = true
    get(u, h, 'looking for a feed', function(resp, final)
      local b = resp and body_of(resp)
      if b and F.is_feed(b) then
        local feed = F.parse_feed(b)
        cb('feed', { url = final, title = feed and feed.title or '' })
      else
        try_guess(base, list, k + 1)
      end
    end)
  end
  get(url, h, 'looking at the address', function(resp, final)
    if not resp then cb(nil, final); return end
    local st = tonumber(resp.status) or 0
    if st >= 400 then cb(nil, 'HTTP ' .. st); return end
    local b = body_of(resp) or ''
    extend()
    if F.is_opml(b) then cb('opml', { title = F.parse_opml(b).title, text = b }); return end
    if F.is_feed(b) then
      local feed = F.parse_feed(b)
      cb('feed', { url = final, title = feed and feed.title or '' })
      return
    end
    local found = looks_html(b) and F.discover(b, final) or {}
    local guesses = {}
    for _, d in ipairs(found) do guesses[#guesses + 1] = d.url end
    for _, p in ipairs({ '/feed', '/rss', '/feed.xml', '/atom.xml', '/index.xml', '/rss.xml' }) do guesses[#guesses + 1] = p end
    try_guess(final, guesses)
  end)
end

L.MY = MY
return L
end

-- RSS reader for XTOS Licorice, API 2.18. Two kinds of sources, side by side in one menu:
-- CommaFeed accounts through a commafeed-opds Worker's JSON API, and feeds the reader fetches
-- itself, kept in collections (OPML files in the app's folder on the card; library.lua, feeds.lua).
-- The Worker, when set, also gives those feeds full text (/api/read) and fetches the very large
-- ones (/api/feed). Decodes with ctx.json and keeps an offline cache in ctx.storage.
--
-- Screens: menu (sources, then Unread / Starred / All / Feeds / Tags or Add feed / Settings), list
-- (paged, tap an item), article (word-wrapped text, paged), feeds, tags, add, catalog, settings.
-- Every ctx.* function is a method on this API: colon calls everywhere.

local F = require('feeds')
local Lib = require('library')
local A = require('ai')
local SITE = 'https://omer-faruq-xteink.github.io/touch-licorice-apps/'
local GUIDE = SITE .. 'tools/worker/?for=rss-local'
local CATALOG = SITE .. 'rss/catalog.json'

-- Portrait (480 x 800) or landscape (800 x 480), chosen in Settings (the manifest asks for API 2.18):
-- the layout follows ctx.screen's size, a list page holds the rows that fit (12 or 6) and asks
-- the Worker for that many, the menu and Settings take two columns, and after turning, the
-- article and the preview are laid out again at the same place.
local W, H, TOP = 480, 800, 56
local QR_PX = 200             -- the source QR code at the end of an article, at most this wide
local LIST_N = 12             -- list rows a page: the rows that fit (sync_screen)
local LIST_MAX_ITEMS = 240    -- list rows kept in memory as pages are appended
local TEXT_MAX = 20000

local G, ERR = nil, nil
local screen = 'menu'
local status = ''
local loading = nil           -- text shown while a request is in flight
local function now_ms()
  local ok, t = pcall(function() return ctx.clock:millis() end)
  return ok and tonumber(t) or nil
end

-- Wi-Fi: ctx.net:keep_wifi(n) takes MILLISECONDS (probe round 11: keep_wifi(300) let Wi-Fi drop
-- within 10 s, keep_wifi(300000) kept it up). The app once passed 120 meaning seconds, so with
-- Wi-Fi off in the settings every request paid ~7 s for Wi-Fi to come up again. Now: kept up for
-- 5 minutes from the last tap or request while the app is open, released when it is left.
local WIFI_KEEP_MS = 5 * 60 * 1000
local wifi_kept_at = nil
local function keep_wifi(force)
  local t = now_ms()
  if not force and t and wifi_kept_at and t - wifi_kept_at < 30000 then return end
  wifi_kept_at = t
  pcall(function() ctx.net:keep_wifi(WIFI_KEEP_MS) end)
end

-- Network queue. The host appears to carry one request at a time: a second one started while
-- another is in flight never got an answer (the feeds list stayed on "loading"). So requests
-- run one after the other, images included. A request with no answer within its timeout is
-- cancelled and reported as failed, and the next one starts.
local function short(s, n) s = tostring(s); if #s > n then return s:sub(1, n - 1) .. '~' end return s end
-- a character limit set for the 480 px portrait width, scaled to the screen's width now
local function wide(n) return math.max(8, math.floor(n * W / 480)) end
-- s cut to fit maxw pixels in font f, whole UTF-8 characters, with "~" where it was cut
local function fit(s, f, maxw)
  s = tostring(s)
  if not f then return short(s, math.floor(maxw / 11)) end
  local function wd(t) local ok, m = pcall(function() return f:measure(t) end); return (ok and type(m) == 'number') and m or #t * 11 end
  if wd(s) <= maxw then return s end
  local n = utf8.len(s)
  if not n then return short(s, math.floor(maxw / 11)) end
  local lo, hi = 0, n - 1                         -- characters kept, found by halving
  while lo < hi do
    local mid = (lo + hi + 1) // 2
    if wd(s:sub(1, (utf8.offset(s, mid + 1) or #s + 1) - 1) .. '~') <= maxw then lo = mid else hi = mid - 1 end
  end
  return s:sub(1, (utf8.offset(s, lo + 1) or #s + 1) - 1) .. '~'
end
local net_queue, net_active = {}, nil
local net_pump

local function net_finish(job, resp, err)
  if job.done then return end                 -- a late answer after a timeout is ignored
  job.done = true
  if net_active == job then net_active = nil end
  if not net_active and #net_queue == 0 then loading = nil end
  job.on_result(resp, err)
  net_pump()
  pcall(function() ctx:invalidate() end)
end

net_pump = function()
  if net_active or #net_queue == 0 then return end
  local job = table.remove(net_queue, 1)
  net_active = job
  job.since = now_ms()
  loading = job.label
  local ok, err = pcall(function()
    job.handle = ctx.net:request(job.opts, function(c, resp) net_finish(job, resp, nil) end)
  end)
  if not ok then net_finish(job, nil, short(err, 60)) end
end

-- drop the request in flight: cancel it in the host and report it as failed
local function net_abandon(reason)
  local job = net_active
  if not job then return end
  if job.handle then pcall(function() job.handle:cancel() end) end
  net_finish(job, nil, reason)
end

-- still waiting for an answer? Also enforces the timeouts (checked on every draw and input).
local function busy()
  if net_active then
    local t = now_ms()
    if t and net_active.since and t - net_active.since > net_active.timeout then
      net_abandon('no answer within ' .. math.floor(net_active.timeout / 1000) .. ' s')
    end
  end
  return net_active ~= nil or #net_queue > 0
end

-- Reload: a request that has been waiting a while is given up at once instead of after its timeout
local function net_unstick()
  local t = now_ms()
  if net_active and (not t or not net_active.since or t - net_active.since > 3000) then
    net_abandon('given up (Reload)')
  end
end

local function net_submit(opts, label, timeout, on_result)
  opts.timeout_ms = timeout
  net_queue[#net_queue + 1] = { opts = opts, label = label, timeout = timeout, on_result = on_result }
  net_pump()
end
local cfg = { host = '', token = '', auth = '', full = false, size = 'default', images = false, screen = 'portrait',
              aion = false, aiprov = 'claude', aiurl = '', aikey = '', aimodel = '', ailang = '', aiextra = '' }   -- AI: A.DEFAULTS
-- Text size for articles and the preview. The firmware has three fonts (ttf is off), so the
-- sizes shift which of them the body, the headings and the feed / date line use.
local SIZES = {
  small = { title = 'medium', head = 'medium', body = 'small', meta = 'small' },
  default = { title = 'large', head = 'large', body = 'medium', meta = 'small' },
  large = { title = 'large', head = 'large', body = 'large', meta = 'medium', rule = true },
}
local SIZE_ORDER = { 'default', 'large', 'small' }
local function st() return SIZES[cfg.size] or SIZES.default end
-- CommaFeed accounts the Worker serves ({ {id, label} ... }, from /api). With more than one the
-- menu starts with a folder per account and every request carries ?acct=<id>.
local accounts = {}
local acct = nil              -- the chosen account's id while several exist
local has_cf = true           -- false when /api says the Worker has no CommaFeed account (full text only)
local function multi() return #accounts > 1 end
local read_accounts, load_accounts, note_accounts   -- defined in the accounts section
-- The account list is asked (/api, a tiny answer) as soon as the app starts: that request also
-- brings Wi-Fi up (~7 s with Wi-Fi off in the settings), which the first list needs anyway, so a
-- list opened meanwhile waits only for the rest. Lists and feed answers carry the account list
-- too and keep it current; an older Worker without that is asked /api once more after Settings.
-- No timer: timeouts are checked on draw and input.
local accounts_fresh = false
-- feeds on the reader: the collections (OPML files) and where the menu is: nil (the sources, or
-- the only source), 'cf' (a CommaFeed account; acct when there are several) or 'local' (coll)
local coll_list = {}
local where, coll = nil, nil
local load_page_images, release_images, draw_image_line   -- defined in the images section
local draw_source_line                                    -- the source QR block, images section
local settings_list, setting_rect, sync_screen   -- defined with Settings / before on_input
local function acct_label()
  for _, a in ipairs(accounts) do if a.id == acct then return a.label end end
  return ''
end
-- cache files of accounts other than the first get their own prefix, so nothing mixes
local function cpre() return (multi() and acct and acct ~= '1') and ('x' .. acct .. '_') or '' end

-- list screen
local list = { kind = 'unread', id = nil, title = '', page = 1, items = {}, has_more = false, cached = false }
-- long-press preview over the list: { item, lines, box = {x, y, w, h}, open = {..}, close = {..} }
local preview = nil
local suppress_up = false     -- the release that ends a long press must not also act as a tap
local preview_can             -- defined with the preview navigation; draw_preview needs it
local article_back            -- Back from an article: to its preview if it was opened there
-- feeds and tags screens: the same rows, one name each (a tag's opens its articles)
local feeds = { items = {}, top = 1, path = {} }   -- path: the folder open in a collection's feeds
local tags = { items = {}, top = 1 }
local function names() return screen == 'tags' and tags or feeds end
local function on_names() return screen == 'feeds' or screen == 'tags' end
-- article screen
local art = { id = nil, title = '', feed = '', date = '', lines = {}, starts = { 1 }, page = 1, pages = 1, cached = false }
local measure_cache = {}

local function note(s) status = tostring(s or '') end
local function urlenc(s)
  return (tostring(s):gsub('[^%w%-%._~]', function(ch) return string.format('%%%02X', ch:byte()) end))
end
-- an article's tags as one line ("a, b"), from the list item. The Worker sends them as the
-- string tag_line too: the preview showed no tags while the Worker sent them as an array.
local function tag_text(item)
  if type(item.tag_line) == 'string' then return item.tag_line end
  local t = {}
  for _, name in ipairs(type(item.tags) == 'table' and item.tags or {}) do t[#t + 1] = tostring(name) end
  return table.concat(t, ', ')
end

local function refresh() pcall(function() ctx:invalidate() end) end

-- A side button arrives as more than one key event on API 2.9 (press and release, or a repeat),
-- which turned one press into two pages. Ignore release events and the same key again within
-- KEY_GAP_MS, whatever the host calls its fields.
local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
local function key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local now = tonumber(ev.time_ms)
  if not now then
    local ok, m = pcall(function() return ctx.clock:millis() end)
    now = ok and tonumber(m) or nil
  end
  if now and last_key == ev.key and last_key_ms and now - last_key_ms >= 0 and now - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, now
  return true
end

------------------------------------------------------------------ config

local function load_cfg()
  local ok, s = pcall(function() return ctx.storage:read('config.txt') end)
  if ok and type(s) == 'string' then
    for k, v in s:gmatch('(%w+)=([^\n]*)') do
      if k == 'full' then cfg.full = (v == '1')
      elseif k == 'images' then cfg.images = (v == '1')
      elseif k == 'aion' then cfg.aion = (v == '1')
      elseif k == 'size' then cfg.size = SIZES[v] and v or 'default'
      elseif k == 'screen' then cfg.screen = v:match('^landscape') and 'landscape' or 'portrait'
      else cfg[k] = v end
    end
  end
end

local function save_cfg()
  pcall(function()
    local s = 'host=' .. cfg.host .. '\ntoken=' .. cfg.token .. '\nauth=' .. cfg.auth .. '\nfull=' .. (cfg.full and '1' or '0') .. '\nsize=' .. cfg.size .. '\nimages=' .. (cfg.images and '1' or '0') .. '\nscreen=' .. cfg.screen
    -- the AI lines only once something of it is set
    ctx.storage:write('config.txt', s .. A.cfg_lines(cfg))
  end)
end

local function base_url()
  local host = cfg.host:gsub('^https?://', ''):gsub('/+$', '')
  if host == '' then return nil end
  local u = 'https://' .. host
  if cfg.token ~= '' then u = u .. '/k/' .. cfg.token end
  return u
end

------------------------------------------------------------------ network

local function request_target(path, accept)
  local base = base_url()
  if not base then return nil end
  local url = base .. path
  if multi() and acct then url = url .. (url:find('?', 1, true) and '&' or '?') .. 'acct=' .. acct end
  if cfg.full then url = url .. (url:find('?', 1, true) and '&' or '?') .. 'full=1' end
  local headers = { ['Accept'] = accept or 'application/json' }
  if cfg.auth ~= '' then
    local ok, b64 = pcall(function() return ctx.base64:encode(cfg.auth) end)
    if ok and b64 then headers['Authorization'] = 'Basic ' .. b64 end
  end
  return url, headers
end

-- the bytes of an article image, straight from the resizer URL the Worker gave (another host:
-- no Worker credentials go with it); on_done(body) or on_done(nil, err)
local function fetch_image(url, on_done)
  local headers = { ['Accept'] = 'image/jpeg', ['User-Agent'] = 'Mozilla/5.0 (Xteink RSS mini app)' }
  net_submit({ url = url, method = 'GET', headers = headers }, loading or 'loading image', 30000, function(resp, err)
    if err then on_done(nil, err); return end
    local st = type(resp) == 'table' and (tonumber(resp.status) or tonumber(resp.code)) or nil
    local body = type(resp) == 'table' and resp.body or nil
    if type(body) ~= 'string' or (st and st >= 400) then on_done(nil, 'HTTP ' .. tostring(st)); return end
    on_done(body)
  end)
end

local function request(path, on_done, label)
  local url, headers = request_target(path)
  if not url then note('set the host in Settings'); on_done(nil, 'no host'); return end
  keep_wifi()
  -- articles may wait for the Worker's full-text services; lists answer quickly
  local timeout = path:find('/api/article/', 1, true) and 60000 or 30000
  net_submit({ url = url, method = 'GET', headers = headers }, label or ('loading ' .. short(path, 30)), timeout, function(resp, err)
    if err then on_done(nil, err); return end
    if type(resp) ~= 'table' then on_done(nil, 'no response'); return end
    local st = tonumber(resp.status) or tonumber(resp.code)
    local body = resp.body
    if resp.error and not body then on_done(nil, tostring(resp.error)); return end
    if st and st >= 400 then on_done(nil, 'HTTP ' .. st .. ' ' .. short(body or '', 40)); return end
    if type(body) ~= 'string' then on_done(nil, 'empty body'); return end
    local okj, data = pcall(function() return ctx.json:decode(body) end)
    if not okj or type(data) ~= 'table' then on_done(nil, 'bad json: ' .. short(body, 40)); return end
    if data.error then on_done(nil, tostring(data.error)); return end
    note_accounts(data, body, path)
    on_done(data, nil, body)
  end)
  refresh()
end

local function cache_write(name, s) pcall(function() ctx.storage:write(name, s) end) end
local function cache_read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  if ok and type(s) == 'string' then return s end
  return nil
end

-- Offline copies of articles: the CACHE_KEEP most recently opened stay, older ones are removed.
-- cache_idx.txt lists them, oldest first; copies made before that list existed go in front.
local CACHE_KEEP, CACHE_IDX = 100, 'cache_idx.txt'
local cache_names = nil
local clear_armed = false            -- Settings: the first tap on the offline row asks for a second
local function is_copy(n) return n:match('^a%d+i?%.txt$') or n:match('^x%d+_a%d+i?%.txt$') or n:match('^b%x+i?%.txt$') end
local function copies()
  if cache_names then return cache_names end
  cache_names = {}
  local raw = cache_read(CACHE_IDX)
  if raw then
    for n in raw:gmatch('[^\n]+') do cache_names[#cache_names + 1] = n end
  else
    local ok, t = pcall(function() return ctx.storage:list() end)
    for _, e in ipairs((ok and type(t) == 'table') and t or {}) do
      local n = type(e) == 'table' and e.name or e
      if type(n) == 'string' and is_copy(n) then cache_names[#cache_names + 1] = n end
    end
    table.sort(cache_names)
  end
  return cache_names
end
local function cache_remove(name) pcall(function() ctx.storage:remove(name) end) end
local function cache_save()
  cache_write(CACHE_IDX, table.concat(cache_names, '\n'))
end
-- name was just read or written: it moves to the end, the oldest beyond CACHE_KEEP go
local function cache_touch(name)
  local out = {}
  for _, n in ipairs(copies()) do if n ~= name then out[#out + 1] = n end end
  out[#out + 1] = name
  while #out > CACHE_KEEP do cache_remove(table.remove(out, 1)) end
  cache_names = out
  cache_save()
end
local function cache_clear()
  for _, n in ipairs(copies()) do cache_remove(n) end
  cache_names = {}
  cache_save()
end

------------------------------------------------------------------ text layout

local function measure(font, s)
  local key = s
  local w = measure_cache[key]
  if w then return w end
  local ok, m = pcall(function() return font:measure(s) end)
  w = (ok and type(m) == 'number') and m or (#s * 11)
  measure_cache[key] = w
  return w
end

-- wrap one paragraph into lines no wider than width using the font's measure;
-- each line is appended to out as { s = text, f = fname, h = line height, x = indent }
-- an address (no spaces) cut into lines that fit width in the small font, preferably after
-- / . - ? & =; at most max_lines, the last one ending in "~" when the address is longer
local function wrap_address(s, width, max_lines)
  local font = ctx.fonts and ctx.fonts.small
  local function wd(t)
    local ok, m = pcall(function() return font:measure(t) end)
    return (ok and type(m) == 'number') and m or (#t * 11)
  end
  local lines = {}
  while #s > 0 and #lines < max_lines do
    if wd(s) <= width then lines[#lines + 1] = s; return lines end
    local n = 1
    while n < #s and wd(s:sub(1, n + 1)) <= width do n = n + 1 end
    if #lines == max_lines - 1 then lines[#lines + 1] = s:sub(1, math.max(1, n - 1)) .. '~'; return lines end
    local cut = n
    for i = n, math.max(1, n - 12), -1 do
      if s:sub(i, i):match('[/%.%-%?&=]') then cut = i; break end
    end
    lines[#lines + 1] = s:sub(1, cut)
    s = s:sub(cut + 1)
  end
  return lines
end

local function wrap_para(out, para, fname, width, indent)
  local F = ctx.fonts
  local font = F and F[fname]
  local okl, lh = pcall(function() return font.line_height end)
  lh = (okl and tonumber(lh)) or (fname == 'large' and 30 or fname == 'small' and 20 or 24)
  local function push(s) out[#out + 1] = { s = s, f = fname, h = lh, x = indent } end
  if not font then push(para); return end
  local line, lw = '', 0
  local space_w = measure(font, ' ')
  for word in para:gmatch('%S+') do
    local ww = measure(font, word)
    if ww > width then
      -- long word: flush and split by characters
      if line ~= '' then push(line); line, lw = '', 0 end
      local piece = ''
      for ch in word:gmatch('[%z\1-\127\194-\244][\128-\191]*') do
        if measure(font, piece .. ch) > width then push(piece); piece = ch else piece = piece .. ch end
      end
      line, lw = piece, measure(font, piece)
    elseif line == '' then line, lw = word, ww
    elseif lw + space_w + ww <= width then line, lw = line .. ' ' .. word, lw + space_w + ww
    else push(line); line, lw = word, ww end
  end
  if line ~= '' then push(line) end
end

-- paragraphs come separated by blank lines; "# " marks a heading, "> " a quote, "• " a list item
local function layout_article(data)
  art.data = data               -- kept, so turning the screen can lay it out again
  measure_cache = {}
  local out = {}
  local function gap(h) out[#out + 1] = { s = '', f = 'small', h = h, x = 0 } end
  local S = st()
  wrap_para(out, data.title or '', S.title, W - 24, 0)
  local meta = ((data.feed or '') ~= '' and (data.feed .. '  ') or '') .. (data.date or '') .. ((data.source or 'feed') ~= 'feed' and ('  [' .. data.source .. ']') or '')
  if meta ~= '' then wrap_para(out, meta, S.meta, W - 24, 0) end
  -- when the title is no bigger than the text, a rule under it keeps it apart
  if S.rule then gap(8); out[#out + 1] = { s = '', f = 'small', h = 6, x = 0, rule = true } end
  gap(14)
  local text = data.text or ''
  local info = {}
  for _, im in ipairs(type(data.images) == 'table' and data.images or {}) do
    if type(im) == 'table' and im.n then info[tonumber(im.n)] = im end
  end
  for raw_para in (text .. '\n\n'):gmatch('(.-)\n\n') do
    local para = raw_para:gsub('^\n+', ''):gsub('\n+$', '')  -- Lua 5.5: loop variables are const
    local imgn = tonumber(para:match('^%[%[img:(%d+)%]%]$'))
    if imgn then
      local im = info[imgn]
      if im and tonumber(im.w) and tonumber(im.h) then
        local iw, ih, isrc = tonumber(im.w), tonumber(im.h), tostring(im.src or '')
        local room = H - TOP - 52            -- a picture fits on one page (in landscape: smaller)
        if ih > room then
          iw, ih = math.max(16, iw * room // ih), room
          isrc = isrc:gsub('([?&]w=)%d+', '%1' .. iw):gsub('([?&]h=)%d+', '%1' .. ih)
        end
        out[#out + 1] = { s = '', f = 'small', h = ih + 12, x = 0, img = imgn, iw = iw, ih = ih, src = isrc }
      end
    elseif para ~= '' then
      for line in (para .. '\n'):gmatch('([^\n]*)\n') do
        if line:sub(1, 2) == '# ' then wrap_para(out, line:sub(3), S.head, W - 24, 0)
        elseif line:sub(1, 2) == '> ' then wrap_para(out, line:sub(3), S.body, W - 48, 24)
        elseif line:sub(1, 4) == '• ' then wrap_para(out, line, S.body, W - 40, 16)  -- the bullet is 3 UTF-8 bytes
        elseif line ~= '' then wrap_para(out, line, S.body, W - 24, 0) end
      end
      gap(10)
    end
  end
  -- the article's link as a QR code under a rule (drawn by draw_source_line; just the address
  -- when no QR can be made)
  local url = type(data.url) == 'string' and data.url or ''
  if url:match('^https?://') then
    local addr = wrap_address(url:gsub('^https?://', ''):gsub('^www%.', ''), W - 24, 3)
    gap(6)
    out[#out + 1] = { s = '', f = 'small', h = 6, x = 0, rule = true }
    out[#out + 1] = { s = '', f = 'small', h = 30 + QR_PX + 12 + #addr * 22, x = 0, source = url, addr = addr }
  end
  -- paginate by height
  art.lines = out
  art.starts = { 1 }
  local avail, used = H - TOP - 40, 0
  for i, ln in ipairs(out) do
    if used + ln.h > avail and used > 0 then art.starts[#art.starts + 1] = i; used = 0 end
    used = used + ln.h
  end
  art.pages = #art.starts
  art.page = 1
  art.title = data.title or ''
end

------------------------------------------------------------------ loaders

-- The list keeps every page fetched so far in list.items and shows LIST_N rows from list.top.
-- Next (button, side key or swipe) on the last screen fetches the following page while the
-- Worker says there is more, and appends it; the new rows start on the next screen.

local function list_cache_name(page)
  local n = list.n or LIST_N
  -- a tag name may hold any character: hex for anything but letters and digits
  local id = tostring(list.id or '0'):gsub('[^%w]', function(ch) return string.format('_%02x', ch:byte()) end)
  return cpre() .. 'l_' .. list.kind .. '_' .. id .. '_' .. page .. (n ~= 12 and ('n' .. n) or '') .. '.txt'
end


local function open_list(kind, id, title)
  list.kind, list.id, list.title, list.page = kind, id, title or kind, 0
  list.items, list.has_more, list.cached, list.top = {}, false, false, 1
  list['local'] = nil
  preview = nil
  screen = 'list'
end

-- Each row's tag_line, read from the answer's text rather than the decoded table: on the reader
-- the preview showed no tags while list items carried them as an array, so the decoded table
-- is not trusted with them. The Worker writes "id" first in every item and "tag_line" after it.
local function raw_tag_lines(items, raw)
  if type(raw) ~= 'string' then return end
  local found = {}
  for id, line in raw:gmatch('"id":"(%d+)",[^{}]-"tag_line":"(.-)"[,}]') do
    found[id] = line
  end
  for _, it in ipairs(items) do
    local line = found[tostring(it.id)]
    if line then it.tag_line = (line:gsub('\\(.)', '%1')) end
  end
end

local function apply_page(page, data, append, raw)
  local items = data.items or {}
  raw_tag_lines(items, raw)
  if append then
    local seen = {}
    for _, it in ipairs(list.items) do seen[tostring(it.id)] = true end
    for _, it in ipairs(items) do
      if not seen[tostring(it.id)] then list.items[#list.items + 1] = it end
    end
  else
    list.items, list.top = items, 1
  end
  -- keep the heap in check on very long sessions: drop the oldest rows, keep the view in place
  local extra = #list.items - LIST_MAX_ITEMS
  if extra > 0 then
    for _ = 1, extra do table.remove(list.items, 1) end
    list.top = math.max(1, list.top - extra)
  end
  list.page = page
  list.has_more = data.has_more and true or false
end

-- after(ok) runs once the page is in list.items (from the network or the offline cache)
local function fetch_page(page, append, after, retried)
  local path = '/api/list?kind=' .. list.kind .. '&page=' .. page .. '&n=' .. (list.n or LIST_N)
  if list.id then path = path .. '&id=' .. urlenc(list.id) end
  if not append then list.err = nil end
  request(path, function(data, err, raw)
    local ok = false
    if not data and not retried then          -- a hiccup (Wi-Fi waking up, a slow server): once more
      fetch_page(page, append, after, true)
      return
    end
    if data then
      apply_page(page, data, append, raw)
      list.title = data.title or list.title
      list.cached = false
      note('')
      if raw then cache_write(list_cache_name(page), raw) end
      ok = true
    else
      local raw = cache_read(list_cache_name(page))
      local okj, data2 = pcall(function() return ctx.json:decode(raw) end)
      if raw and okj and type(data2) == 'table' then
        apply_page(page, data2, append, raw)
        list.cached = true
        note('offline: ' .. short(err, 30))
        ok = true
      else
        note(short(err, 44))
        if not append then list.err = err end
      end
    end
    if after then after(ok) end
  end)
end

------------------------------------------------------------------ sources and feeds on the reader

local function tz()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table' and tonumber(t.offset_minutes)) or 0
end

local function reload_colls()
  Lib.forget()
  coll_list = Lib.collections()
  if coll then coll = Lib.collection(coll.file) end
end

-- the menu's sources: CommaFeed (one entry per account) when a Worker is set, then the collections
local function sources()
  local out = {}
  if cfg.host ~= '' and has_cf then
    if multi() then
      for _, a in ipairs(accounts) do out[#out + 1] = { kind = 'cf', id = a.id, label = a.label } end
    else
      out[#out + 1] = { kind = 'cf', label = 'CommaFeed' }
    end
  end
  for _, c in ipairs(coll_list) do out[#out + 1] = { kind = 'local', file = c.file, label = c.title } end
  return out
end

-- the collection open (its feeds screen, a feed's articles), or nil
local function cur_coll()
  if where == 'local' then return coll end
  return nil
end

local LIST_KIND = { unread = 'unread', starred = 'starred', all = 'all', feed = 'feed' }

local function show_local_rows(keep_top)
  local c = cur_coll()
  local rows = c and Lib.items(c, LIST_KIND[list.kind] or 'all', list.id) or {}
  local off = tz()
  local kept = {}
  for i, r in ipairs(rows) do
    if i > LIST_MAX_ITEMS then break end
    r.date = F.format_date(r.d, off)
    kept[#kept + 1] = r
  end
  list.items, list.has_more, list.cached = kept, false, false
  if not keep_top or list.top > #kept then list.top = 1 end
end

local fill_local_feeds        -- defined with the feeds screen

-- the feed whose articles are open; the list follows when it comes in
local function refresh_local(force)
  if not cur_coll() or not list.id then return end
  keep_wifi()
  Lib.refresh({ feeds = { { url = list.id } } }, force, function()
    if screen == 'list' and list['local'] and not preview then show_local_rows(true) end
    if screen == 'feeds' and feeds['local'] then fill_local_feeds() end
    refresh()
  end, function(changed, failed, n)
    if n == 0 then note('up to date')
    elseif failed > 0 then note('the feed could not be loaded')
    else note('') end
    refresh()
  end)
end

local function open_local_list(kind, id, title)
  list.kind, list.id, list.title, list.page = kind, id, title or kind, 1
  list.items, list.has_more, list.cached, list.top, list.err = {}, false, false, 1, nil
  list['local'] = true
  preview = nil
  screen = 'list'
  show_local_rows(false)
  refresh_local(false)
end

-- first page, or Reload; the page size from now on is the rows that fit
local function fetch_list() list['local'] = nil; list.n = LIST_N; fetch_page(1, false) end
local function load_more(after)
  if list.has_more and not busy() then fetch_page(list.page + 1, true, after); return true end
  return false
end

local open_local_article      -- feeds on the reader: below

local function open_article(item)
  if item['local'] then open_local_article(item); return end
  art.id, art.title, art.feed, art.date = tostring(item.id), item.title or '', item.feed or '', item.date or ''
  art.lines, art.starts, art.page, art.pages, art.cached = {}, { 1 }, 1, 1, false
  art.from_preview = nil
  screen = 'article'
  release_images()
  local cname = cpre() .. 'a' .. art.id .. (cfg.images and 'i' or '') .. '.txt'
  local cached = cache_read(cname)
  if cached then
    local okj, data = pcall(function() return ctx.json:decode(cached) end)
    if okj and type(data) == 'table' then
      layout_article(data); art.cached = true; note('cached'); cache_touch(cname); load_page_images()
      -- the copy is from an earlier visit: mark it read again if it is unread now (offline: no matter)
      if not item.read then item.read = true; request('/api/mark/' .. art.id .. '?read=1', function() end, 'marking read') end
      return
    end
  end
  request('/api/article/' .. art.id .. '?max=' .. TEXT_MAX .. '&mark=1' .. (cfg.images and '&images=1' or ''), function(data, err, raw)
    if data then
      layout_article(data); note('')
      load_page_images()
      if raw then cache_write(cname, raw); cache_touch(cname) end
      item.read = true
    else
      note(short(err, 44))
    end
  end)
end

-- An article of a feed on the reader: its own text when the feed carries it, else the full text
-- through the Worker (when Full text is on), else the summary, saying how to get more.
open_local_article = function(item)
  art.id = 'l' .. F.hash(item.feed_url .. '|' .. item.id)
  art.title, art.feed, art.date = item.title or '', item.feed or '', item.date or ''
  art.lines, art.starts, art.page, art.pages, art.cached = {}, { 1 }, 1, 1, false
  art.from_preview = nil
  screen = 'article'
  release_images()
  if not item.read then Lib.mark(item, 'r', true) end
  local function show(text, imgs, source)
    layout_article({ title = item.title, feed = item.feed, date = item.date, url = item.url, text = text, images = imgs, source = source })
    load_page_images()
  end
  local summary = (item.excerpt and item.excerpt ~= '') and item.excerpt or '(no summary in the feed)'
  local html = item.has_text and not item.via_worker and Lib.content(item) or nil
  if html and not cfg.full then
    local imgs = cfg.images and {} or nil
    show(F.html_to_text(html, TEXT_MAX, imgs, item.url), imgs)
    return
  end
  local worker = base_url() ~= nil
  if worker and item.url and (cfg.full or item.via_worker) then
    local path = cfg.full and ('/api/read?max=' .. TEXT_MAX .. '&url=' .. urlenc(item.url))
      or ('/api/feed?url=' .. urlenc(item.feed_url) .. '&id=' .. urlenc(item.id) .. '&max=' .. TEXT_MAX)
    if cfg.images then path = path .. '&images=1' end
    local cname = 'b' .. F.hash(path) .. (cfg.images and 'i' or '') .. '.txt'
    local cached = cache_read(cname)
    local okj, data = false, nil
    if cached then okj, data = pcall(function() return ctx.json:decode(cached) end) end
    if okj and type(data) == 'table' then
      data.title, data.feed, data.date, data.url = item.title, item.feed, item.date, item.url
      layout_article(data); art.cached = true; note('cached'); cache_touch(cname); load_page_images()
      return
    end
    local id = art.id
    request(path, function(d, err, raw)
      if art.id ~= id then return end
      if d and type(d.text) == 'string' and d.text ~= '' then
        d.title, d.feed, d.date, d.url = item.title, item.feed, item.date, item.url
        layout_article(d); note('')
        load_page_images()
        if raw then cache_write(cname, raw); cache_touch(cname) end
      elseif html then                                -- the feed's own text, when the service fails
        local imgs = cfg.images and {} or nil
        show(F.html_to_text(html, TEXT_MAX, imgs, item.url), imgs)
        note('full text: ' .. short(err or 'nothing found', 30))
      else
        show(summary .. '\n\n(The full text could not be loaded: ' .. short(err or 'nothing found', 40) .. '.)')
      end
    end, cfg.full and 'loading the full text' or 'loading the article')
    return
  end
  if html then
    local imgs = cfg.images and {} or nil
    show(F.html_to_text(html, TEXT_MAX, imgs, item.url), imgs)
    return
  end
  if cfg.full then
    show(summary .. '\n\nOnly a summary is in this feed. The whole article needs a Worker: see Settings, Full text.')
  else
    show(summary .. '\n\nOnly a summary is in this feed.' .. (worker and ' Full text in Settings fetches the whole article through your Worker.' or ''))
  end
end

local function fetch_feeds(retried)
  feeds['local'] = nil
  screen = 'feeds'
  feeds.items, feeds.top, feeds.err = {}, 1, nil
  request('/api/feeds', function(data, err, raw)
    if not data and not retried then fetch_feeds(true); return end   -- once more before giving up
    if data then feeds.items = data.items or {}; note(''); if raw then cache_write(cpre() .. 'feeds.txt', raw) end
    else
      local raw2 = cache_read(cpre() .. 'feeds.txt')
      local okj, d2 = pcall(function() return ctx.json:decode(raw2) end)
      if raw2 and okj and type(d2) == 'table' then feeds.items = d2.items or {}; note('offline: ' .. short(err, 30))
      else note(short(err, 44)); feeds.err = err end
    end
  end)
end

-- a collection's feeds screen: Add feed, then the folders of the open folder (feeds.path) and its
-- feeds, each with its unread count (from the index: no feed's file is read here); a feed that
-- could not be loaded last time says so
local function under(f, path)
  local p = f.path or {}
  if #p < #path then return false end
  for i, n in ipairs(path) do if p[i] ~= n then return false end end
  return true
end

fill_local_feeds = function()
  local c = cur_coll()
  local path = feeds.path
  local items, folders, seen = {}, {}, {}
  if #path == 0 then items[1] = { kind = 'add', name = 'Add feed' } end
  local list_feeds = {}
  for _, f in ipairs(c and c.feeds or {}) do
    if under(f, path) then
      local p = f.path or {}
      if #p == #path then list_feeds[#list_feeds + 1] = f
      else
        local name = p[#path + 1]
        if not seen[name] then seen[name] = { kind = 'folder', folder = name, n = 0 }; folders[#folders + 1] = seen[name] end
        seen[name].n = seen[name].n + 1
      end
    end
  end
  for _, d in ipairs(folders) do
    d.name = d.folder .. '/  (' .. d.n .. (d.n == 1 and ' feed)' or ' feeds)')
    items[#items + 1] = d
  end
  for _, f in ipairs(list_feeds) do
    local info = Lib.info(f.url)
    local name = (f.title and f.title ~= '' and f.title ~= f.url) and f.title or f.url
    items[#items + 1] = { id = f.url, name = name .. (info.e and '  (!)' or ''), unread = info.u or 0, ['local'] = true }
  end
  feeds.items = items
  if feeds.top > #items then feeds.top = 1 end
end

-- keep: back from a feed's articles, to the same folder and screen of rows
local function open_local_feeds(keep)
  screen = 'feeds'
  feeds['local'] = true
  feeds.err = nil
  if not keep then feeds.items, feeds.top, feeds.path = {}, 1, {} end
  fill_local_feeds()
end

-- Back in a collection's feeds: up one folder, then to the menu
local function local_feeds_back()
  if #feeds.path > 0 then
    local name = table.remove(feeds.path)
    feeds.top = 1
    fill_local_feeds()
    for i, it in ipairs(feeds.items) do
      if it.kind == 'folder' and it.folder == name then feeds.top = math.floor((i - 1) / LIST_N) * LIST_N + 1 end
    end
  else
    screen, where, coll = 'menu', nil, nil
  end
end

